export const questMessagesEn: Record<string, string> = {
  "quest.common.banished": "\"You have betrayed all those who hold allegiance to {qd}, as you once did.\nMy allegiance to {qd} holds fast and I cannot condone or accept what you\nhave done.\n\nLeave this place.  You shall never set foot at {qH} again.\nThat which you seek is now lost forever, for without the Bell of Opening,\nyou will never be able to enter the place where he who has the Amulet\nresides.\n\nGo now!  You are banished from this place.",
  "quest.common.banished.synopsis": "[You are banished from {qH} for betraying your allegiance to {qd}.]",
  "quest.common.legacy": "It is written in the Book of {qd}:\n\n    After the Creation, the cruel god Moloch rebelled\n    against the authority of Marduk the Creator.\n    Moloch stole from Marduk the most powerful of all\n    the artifacts of the gods, the Amulet of Yendor,\n    and he hid it in the dark cavities of Gehennom, the\n    Under World, where he now lurks, and bides his time.\n\nYour {qG} {qd} seeks to possess the Amulet, and with it\nto gain deserved ascendance over the other gods.\n\nYou, a newly trained {qr}, have been heralded\nfrom birth as the instrument of {qd}.  You are destined\nto recover the Amulet for your deity, or die in the\nattempt.  Your hour of destiny has come.  For the sake\nof us all:  Go bravely with {qd}!",
  "quest.common.legacy.synopsis": "[{qd|C} has chosen you to recover the Amulet of Yendor for {qd_him|C}.]",
  "quest.common.pauper_legacy": "It is written in the Book of {qd}:\n\n    After the Creation, the cruel god Moloch rebelled\n    against the authority of Marduk the Creator.\n    Moloch stole from Marduk the most powerful of all\n    the artifacts of the gods, the Amulet of Yendor,\n    and he hid it in the dark cavities of Gehennom, the\n    Under World, where he now lurks, and bides his time.\n\nYour {qG} {qd} seeks to possess the Amulet, and with it\nto gain deserved ascendance over the other gods.\n\nYou, an untrained {qr}, have been unable to adequately\nprepare to be the instrument of {qd}.  Nevertheless, you\nare destined to recover the Amulet for your deity, or die\nin the attempt.  Your hour of destiny has come.  For the\nsake of us all:  Go bravely with {qd}!",
  "quest.common.pauper_legacy.synopsis": "[{qd|C} has chosen you to recover the Amulet of Yendor for {qd_him|C}.]",
  "quest.common.quest_complete_no_bell": "\"The silver bell which was hoarded by {qn} will be\nessential in locating the Amulet of Yendor.\"",
  "quest.common.quest_complete_no_bell.synopsis": "[\"The silver bell which was hoarded by {qn} will be essential in locating the Amulet of Yendor.\"]",
  "quest.common.quest_portal.1": "You receive a faint telepathic message from {ql}:",
  "quest.common.quest_portal.2": "Your help is urgently needed at {qH}!",
  "quest.common.quest_portal.3": "Look for a ...ic transporter.",
  "quest.common.quest_portal.4": "You couldn't quite make out that last message.",
  "quest.common.quest_portal_again": "You again sense {ql} pleading for help.",
  "quest.common.quest_portal_demand": "You again sense {ql} demanding your attendance.",
  "quest.arc.assignquest": "\"Grave times have befallen the college, for {qn|an} has\nstolen {qo}.  Without it, the board of directors of\nthe university will soon have no choice but to revoke our research grants.\n\n\"You must locate the entrance to {qi}.  Within it,\nyou will find {qn}.\n\n\"You must then defeat {qn} and return {qo}\nto me.\n\n\"Only in this way will we be able to prevent the budget cuts that could\nclose this college.\n\n\"May the wisdom of {qd} be your guide.\"",
  "quest.arc.assignquest.synopsis": "[{qn|C} has stolen {qo}.  Locate {qi}, defeat {qn_him}, and return {qO}.]",
  "quest.arc.badalign": "\"{qp|C}!  I've heard that you've been using sloppy techniques.  Your\nresults lately can hardly be called suitable for {qr|an}!\n\n\"How could you have strayed from the {qa} path?  Go from here, and come\nback only when you have purified yourself.\"",
  "quest.arc.badalign.synopsis": "[\"{qp|C}, you have strayed from the {qa} path.  Purify yourself!\"]",
  "quest.arc.badlevel": "\"{qp}, you are yet too inexperienced to undertake such a demanding\nquest.  A mere {qr} could not possibly face the rigors demanded and\nsurvive.  Go forth, and come here again when your adventures have further\ntaught you.\"",
  "quest.arc.badlevel.synopsis": "[{qp|C}, a mere {qr} is too inexperienced.]",
  "quest.arc.discourage.1": "\"Try your best, {qp}.  You cannot defeat me.\"",
  "quest.arc.discourage.2": "\"I shall rend the flesh from your body whilst you still breathe!\"",
  "quest.arc.discourage.3": "\"First you, {qp}, then I shall destroy your mentor, {ql}.\"",
  "quest.arc.discourage.4": "\"Tiring yet, {qp}?  I draw my power from my master and cannot falter!\"",
  "quest.arc.discourage.5": "\"I shall rend thy soul from thy body and consume it!\"",
  "quest.arc.discourage.6": "\"You are far too {qa} -- it weakens you.  You shall die in this place.\"",
  "quest.arc.discourage.7": "\"{qd} has forsaken you!  You are lost now!\"",
  "quest.arc.discourage.8": "\"A mere {qr} cannot hope to defeat me!\"",
  "quest.arc.discourage.9": "\"If you are the best {ql} can send, I have nothing to fear.\"",
  "quest.arc.discourage.10": "\"Die {qc}!  I shall exhibit your carcass as a trophy.\"",
  "quest.arc.encourage.1": "\"Beware, for {qn} is powerful and cunning.\"",
  "quest.arc.encourage.2": "\"To locate the entrance to {qi}, you must pass many traps.\"",
  "quest.arc.encourage.3": "\"A {qn|t} may be vulnerable to attacks by magical cold.\"",
  "quest.arc.encourage.4": "\"Call upon {qd} when you encounter {qn}.\"",
  "quest.arc.encourage.5": "\"You must destroy {qn}.  It will pursue you otherwise.\"",
  "quest.arc.encourage.6": "\"{qo|C} is a mighty talisman.  With it you can destroy {qn}.\"",
  "quest.arc.encourage.7": "\"Go forth with the blessings of {qd}.\"",
  "quest.arc.encourage.8": "\"I will have my {qg|Plural} watch for your return.\"",
  "quest.arc.encourage.9": "\"Remember not to stray from the true {qa} path.\"",
  "quest.arc.encourage.10": "\"You may be able to sense {qo} when you are near.\"",
  "quest.arc.firsttime": "You are suddenly in familiar surroundings.  The buildings in the distance\nseem to be those of your old alma mater, but something is wrong.  It feels\nas if there has been a riot recently, or {qH} has\nbeen under siege.\n\nAll of the windows are boarded up, and there are objects scattered around\nthe entrance.\n\nStrange forbidding shapes seem to be moving in the distance.",
  "quest.arc.firsttime.synopsis": "[You arrive at {qH}, but all is not well.]",
  "quest.arc.goal_alt": "You have returned to {qn|s} lair.",
  "quest.arc.goal_first": "A strange feeling washes over you, and you think back to things you\nlearned during the many lectures of {ql}.\n\nYou realize the feeling must be the presence of {qo}.",
  "quest.arc.goal_first.synopsis": "[This strange feeling must be the presence of {qo}.]",
  "quest.arc.goal_next": "The familiar presence of {qo} is in the ether.",
  "quest.arc.gotit": "The power of {qo} flows through your body!  You feel\nas if you could now take on the Wizard of Yendor himself and win, but\nyou know you must return {qo} to {ql}.",
  "quest.arc.gotit.synopsis": "[The power of {qo} flows through your body!  You must return it to {ql}.]",
  "quest.arc.guardtalk_after.1": "\"Did you see Lash LaRue in 'Song of Old Wyoming' the other night?\"",
  "quest.arc.guardtalk_after.2": "\"Hey man, got any potions of hallucination for sale?\"",
  "quest.arc.guardtalk_after.3": "\"I guess you are guaranteed to make full professor now.\"",
  "quest.arc.guardtalk_after.4": "\"So, what was worse, {qn} or your entrance exams?\"",
  "quest.arc.guardtalk_after.5": "\"{qo|C} is impressive, but nothing like the bones I dug up!\"",
  "quest.arc.guardtalk_before.1": "\"Did you see Lash LaRue in 'Song of Old Wyoming' the other night?\"",
  "quest.arc.guardtalk_before.2": "\"Hey man, got any potions of hallucination for sale?\"",
  "quest.arc.guardtalk_before.3": "\"Did you see the artifact {ql} brought back from the last dig?\"",
  "quest.arc.guardtalk_before.4": "\"So what species do *you* think we evolved from?\"",
  "quest.arc.guardtalk_before.5": "\"So you're {ql|s} prize pupil!  I don't know what he sees in you.\"",
  "quest.arc.hasamulet": "\"Congratulations, {qp}.  I wondered if anyone could prevail against\nthe Wizard and the minions of Moloch.  Now, you must embark on one\nfinal adventure.\n\n\"Take the Amulet, and find your way onto the Astral Plane.\nThere you must find the altar of {qd} and sacrifice the\nAmulet on that altar to fulfill your destiny.\n\n\"Remember, your path now should always be upwards.\"",
  "quest.arc.hasamulet.synopsis": "[Take the Amulet to the Astral Plane and sacrifice it at the altar of {qd}.]",
  "quest.arc.killed_nemesis": "The body of {qn} dissipates in a cloud of noxious fumes.",
  "quest.arc.leader_first": "\"Finally you have returned, {qp}.  You were always\nmy most promising student.  Allow me to see if you are ready for the\nmost difficult task of your career.\"",
  "quest.arc.leader_first.synopsis": "[\"You have returned, {qp}, to a difficult task.\"]",
  "quest.arc.leader_last": "\"{qp}, you have failed us.  All of my careful training has been in\nvain.  Begone!  Your tenure at this college has been revoked!\n\n\"You are a disgrace to the profession!\"",
  "quest.arc.leader_last.synopsis": "[\"{qp|C}, you have failed us.  Begone!\"]",
  "quest.arc.leader_next": "\"Again, {qp}, you stand before me.\nLet me see if you have gained experience in the interim.\"",
  "quest.arc.leader_next.synopsis": "[\"Again, {qp}, you stand before me. Let me see if you have gained experience in the interim.\"]",
  "quest.arc.leader_other": "\"Once more, {qp}, you have returned from the field.\nAre you finally ready for the task that must be accomplished?\"",
  "quest.arc.leader_other.synopsis": "[\"Once more, {qp}, you have returned from the field. Are you finally ready for the task that must be accomplished?\"]",
  "quest.arc.locate_first": "A plain opens before you.  Beyond the plain lies a foreboding edifice.\n\nYou have the feeling that you will soon find the entrance to\n{qi}.",
  "quest.arc.locate_first.synopsis": "[This foreboding edifice must hide the entrance to {qi}.]",
  "quest.arc.locate_next": "Once again, you are near the entrance to {qi}.",
  "quest.arc.nemesis_first": "\"So, {qp}, you think that you can succeed in recovering\n{qo}, when your teacher, {ql}, has already failed.\n\n\"Come, try your best!  I shall destroy you, and gnaw on your bones.\"",
  "quest.arc.nemesis_first.synopsis": "[\"Come, {qp}, I shall destroy you!\"]",
  "quest.arc.nemesis_next": "\"Again you try to best me, eh {qp}?  Well, you shall fail again.\n\n\"You shall never recover {qo}.\n\n\"I shall bear your soul to the Plane of Origins for my master's pleasure.\"",
  "quest.arc.nemesis_next.synopsis": "[\"Again you try to best me, {qp}?  You shall never recover {qo}.\"]",
  "quest.arc.nemesis_other": "\"You persist yet {qp}!  Good.  Now, you shall die!\"",
  "quest.arc.nemesis_wantsit": "\"I shall have {qo} from you, {qp}, then feast\nupon your entrails!\"",
  "quest.arc.nemesis_wantsit.synopsis": "[\"I shall have {qo} from you, {qp}, then feast upon your entrails!\"]",
  "quest.arc.nexttime": "Once again, you are back at {qH}.",
  "quest.arc.offeredit": "{ql|C} touches {qo} briefly, gazes into it,\nthen smiles at you and says:\n\n\"Well done, {qp}.  You have defeated {qn} and\nrecovered {qo}.  But I fear that it shall never be safe\nhere.\n\nPlease take {qo} with you.  You, {qp}, can\nguard it now far better than I.\n\nMay the blessings of {qd} follow you and guard you.\"",
  "quest.arc.offeredit.synopsis": "[{ql|C} instructs you to guard {qo} from now on.]",
  "quest.arc.offeredit2": "\"Careful, {qp}!  {qo|C} might break, and that would be\na tragic loss.  You are its keeper now, and the time has come to\nresume your search for the Amulet.  The Dungeons of Doom await your\nreturn through the magic portal that brought you here.\"",
  "quest.arc.offeredit2.synopsis": "[\"Resume your search for the Amulet beyond the magic portal to The Dungeons of Doom.\"]",
  "quest.arc.othertime": "You are back at {qH}.\nYou have an odd feeling this may be the last time you ever come here.",
  "quest.arc.othertime.synopsis": "[You are back at {qH}. You have an odd feeling this may be the last time you ever come here.]",
  "quest.arc.posthanks": "\"Welcome back, {qp}.  Have you progressed with your quest to\nregain the Amulet of Yendor for {qd}?\"",
  "quest.arc.posthanks.synopsis": "[\"Have you progressed with your quest to regain the Amulet of Yendor for {qd}?\"]",
  "quest.bar.assignquest": "\"The world is in great need of your assistance, {qp}.\n\n\"About six months ago, I learned that a mysterious sorcerer, known\nas {qn}, had begun to gather a large group of cutthroats and brigands\nabout {qn_him}.\n\n\"At about the same time, these people you once rode with `liberated' a\npotent magical talisman, {qo}, from a Turanian caravan.\n\n\"{qn|C} and {qn_his} Black Horde swept down upon {qi} and defeated\nthe people there, driving them out into the desert.  He has taken\n{qo}, and seeks to bend it to {qn_his} will.  I detected the\nsubtle changes in the currents of fate, and joined these people.\nThen I sent forth a summons for you.\n\n\"If {qn} can bend {qo} to {qn_his} will, he will become\nalmost indestructible.  He will then be able to enslave the minds of\nmen across the world.  You are the only hope.  The gods smile upon you,\nand with {qd} behind you, you alone can defeat {qn}.\n\n\"You must go to {qi}.  From there, you can track down\n{qn}, defeat {qn_him}, and return {qo} to us.  Only\nthen will the world be safe.\"",
  "quest.bar.assignquest.synopsis": "[\"Find {qn}, defeat {qn_him}, and return {qo} to us.\"]",
  "quest.bar.badalign": "\"{qp|C}!  You have wandered from the path of the {qa}!\nIf you attempt to overcome {qn} in this state, he will surely\nenslave your soul.  Your only hope, and ours, lies in your purification.\nGo forth, and return when you feel ready.\"",
  "quest.bar.badalign.synopsis": "[\"You have wandered from the path of the {qa}.  Come back when you have atoned.\"]",
  "quest.bar.badlevel": "\"{qp}, I fear that you are as yet too inexperienced to face\n{qn}.  Only {qR|an} with the help of {qd} could ever hope to\ndefeat {qn_him}.\"",
  "quest.bar.badlevel.synopsis": "[\"You are too inexperienced.  Come back when you are {qR|an}.\"]",
  "quest.bar.discourage.1": "\"My pets will dine on your carcass tonight!\"",
  "quest.bar.discourage.2": "\"You are a sorry excuse for {qr|an}.\"",
  "quest.bar.discourage.3": "\"Run while you can, {qc}.  My next spell will be your last.\"",
  "quest.bar.discourage.4": "\"I shall use your very skin to bind my next grimoire.\"",
  "quest.bar.discourage.5": "\"{qd} cannot protect you now.  Here, you die.\"",
  "quest.bar.discourage.6": "\"Your {qa} nature makes you weak.  You cannot defeat me.\"",
  "quest.bar.discourage.7": "\"Come, {qc}.  I shall kill you, then unleash the horde on your tribe.\"",
  "quest.bar.discourage.8": "\"Once you are dead, my horde shall finish off {ql}, and your tribe.\"",
  "quest.bar.discourage.9": "\"Fight, {qc}, or are you afraid of the mighty {qn}?\"",
  "quest.bar.discourage.10": "\"You have failed, {qc}.  Now, my victory is complete.\"",
  "quest.bar.encourage.1": "\"{qn|C} is strong in the dark arts, but not immune to cold steel.\"",
  "quest.bar.encourage.2": "\"Remember that {qn} is a great sorcerer.  He lived in the time of Atlantis.\"",
  "quest.bar.encourage.3": "\"If you fail, {qp}, I will not be able to protect these people long.\"",
  "quest.bar.encourage.4": "\"To enter {qi}, you must be very stealthy.  The horde will be on guard.\"",
  "quest.bar.encourage.5": "\"Call upon {qd} in your time of need.\"",
  "quest.bar.encourage.6": "\"May {qd} protect you, and guide your steps.\"",
  "quest.bar.encourage.7": "\"If you can lay hands upon {qo}, carry it for good fortune.\"",
  "quest.bar.encourage.8": "\"I cannot stand against {qn|s} sorcery.  But {qd} will help you.\"",
  "quest.bar.encourage.9": "\"Do not fear {qn}.  I know you can defeat {qn_him}.\"",
  "quest.bar.encourage.10": "\"You have a great road to travel, {qp}, but only after you defeat {qn}.\"",
  "quest.bar.firsttime": "Warily you scan your surroundings, all of your senses alert for signs\nof possible danger.  Off in the distance, you can {qx} the familiar shapes\nof {qH}.\n\nBut why, you think, should {ql} be there?\n\nSuddenly, the hairs on your neck stand on end as you detect the aura of\nevil magic in the air.\n\nWithout thought, you ready your weapon, and mutter under your breath:\n\n    \"By {qd}, there will be blood spilt today.\"",
  "quest.bar.firsttime.synopsis": "[You reach the vicinity of {qH}, but sense evil magic nearby.]",
  "quest.bar.goal_first": "The hairs on the nape of your neck lift as you sense an energy in the\nvery air around you.  You fight down a primordial panic that seeks to\nmake you turn and run.  This is surely the lair of {qn}.",
  "quest.bar.goal_first.synopsis": "[This is surely the lair of {qn}.]",
  "quest.bar.goal_next": "Yet again you feel the air around you heavy with malevolent magical energy.",
  "quest.bar.gotit": "As you pick up {qo}, you feel the power of it\nflowing through your hands.  It seems to be in two or more places\nat once, even though you are holding it.",
  "quest.bar.gotit.synopsis": "[You feel the power of {qo} flowing through your hands.]",
  "quest.bar.guardtalk_after.1": "\"The battles here have been good -- our enemies' blood soaks the soil!\"",
  "quest.bar.guardtalk_after.2": "\"Remember that glory is crushing your enemies beneath your feet!\"",
  "quest.bar.guardtalk_after.3": "\"Times will be good again, now that the horde is vanquished.\"",
  "quest.bar.guardtalk_after.4": "\"You have brought our clan much honor in defeating {qn}.\"",
  "quest.bar.guardtalk_after.5": "\"You will be a worthy successor to {ql}.\"",
  "quest.bar.guardtalk_before.1": "\"The battles here have been good -- our enemies' blood soaks the soil!\"",
  "quest.bar.guardtalk_before.2": "\"Remember that glory is crushing your enemies beneath your feet!\"",
  "quest.bar.guardtalk_before.3": "\"There has been little treasure to loot, since the horde arrived.\"",
  "quest.bar.guardtalk_before.4": "\"The horde is mighty in numbers, but they have little courage.\"",
  "quest.bar.guardtalk_before.5": "\"{ql|C} is a strange one, but he has helped defend us.\"",
  "quest.bar.hasamulet": "\"This is wondrous, {qp}.  I feared that you could not possibly\nsucceed in your quest, but here you are in possession of the Amulet\nof Yendor!\n\n\"I have studied the texts of the magi constantly since you left.  In\nthe Book of Skelos, I found this:\n\n    {qd} will cause a child to be sent into the world.  This child is to\n    be made strong by trial of battle and magic, for {qd} has willed it so.\n    It is said that the child of {qd} will recover the Amulet of Yendor\n    that was stolen from the Creator at the beginning of time.\n\n\"As you now possess the amulet, {qp}, I suspect that the Book\nspeaks of you.\n\n    The child of {qd} will take the Amulet, and travel to the Astral\n    Plane, where the Great Temple of {qd} is to be found.  The Amulet\n    will be sacrificed to {qd}, there on {qd_his|C} altar.  Then the child will\n    stand by {qd} as champion of all {qc|Plural} for eternity.\n\n\"This is all I know, {qp}.  I hope it will help you.\"",
  "quest.bar.hasamulet.synopsis": "[\"Take the Amulet to the altar of {qd} on the Astral Plane and offer it.\"]",
  "quest.bar.killed_nemesis": "{qn|C} falls to the ground, and utters a last curse at you.  Then {qn_his}\nbody fades slowly, seemingly dispersing into the air around you.  You\nslowly become aware that the overpowering aura of magic in the air has\nbegun to fade.",
  "quest.bar.killed_nemesis.synopsis": "[{qn|C} curses you, but you feel the overpowering aura of magic fading.]",
  "quest.bar.leader_first": "\"Ah, {qp}.  You have returned at last.  The world is in dire\nneed of your help.  There is a great quest you must undertake.\n\n\"But first, I must see if you are ready to take on such a challenge.\"",
  "quest.bar.leader_first.synopsis": "[\"At last you have returned.  There is a great quest you must undertake.\"]",
  "quest.bar.leader_last": "\"Pah!  You have betrayed the gods, {qp}.  You will never attain\nthe glory which you aspire to.  Your failure to follow the true path has\nclosed this future to you.\n\n\"I will protect these people as best I can, but soon {qn} will overcome\nme and destroy all who once called you {qs}.  Now begone!\"",
  "quest.bar.leader_last.synopsis": "[\"You have betrayed {qd}; soon {qn} will destroy us.  Begone!\"]",
  "quest.bar.leader_next": "\"{qp}, you are back.  Are you ready now for the challenge?\"",
  "quest.bar.leader_other": "\"Again, you stand before me, {qp}.  Surely you have prepared yourself.\"",
  "quest.bar.locate_first": "The scent of water comes to you in the desert breeze.  You know that\nyou have located {qi}.",
  "quest.bar.locate_first.synopsis": "[You have located {qi}.]",
  "quest.bar.locate_next": "Yet again you have a chance to infiltrate {qi}.",
  "quest.bar.nemesis_first": "\"So.  This is what that second rate sorcerer {ql} sends to do {ql_his} bidding.\nI have slain many before you.  You shall give me little sport.\n\n\"Prepare to die, {qc}.\"",
  "quest.bar.nemesis_first.synopsis": "[{qn|C} boasts that {qn_he} has slain many.  \"Prepare to die, {qc}.\"]",
  "quest.bar.nemesis_next": "\"I have wasted too much time on you already.  Now, you shall die.\"",
  "quest.bar.nemesis_other": "\"You return yet again, {qc}!  Are you prepared for death now?\"",
  "quest.bar.nemesis_wantsit": "\"I shall have {qo} back, you pitiful excuse for {qc|an}.\nAnd your life as well.\"",
  "quest.bar.nemesis_wantsit.synopsis": "[\"I shall have {qo} back, you pitiful excuse for {qc|an}. And your life as well.\"]",
  "quest.bar.nexttime": "Once again, you near {qH}.  You know that {ql}\nwill be waiting.",
  "quest.bar.nexttime.synopsis": "[Once again, you near {qH}.  You know that {ql} will be waiting.]",
  "quest.bar.offeredit": "When {ql} sees {qo}, he smiles, and says:\n\n    Well done, {qp}.  You have saved the world from certain doom.\n    What, now, should be done with {qo}?\n\n    These people, brave as they are, cannot hope to guard it from\n    other sorcerers who will detect it, as surely as {qn} did.\n\n    Take {qo} with you, {qp}.  It will guard you in\n    your adventures, and you can best guard it.  You embark on a\n    quest far greater than you realize.\n\n    Remember me, {qp}, and return when you have triumphed.  I\n    will tell you then of what you must do.  You will understand when the\n    time comes.",
  "quest.bar.offeredit.synopsis": "[{ql|C} tells you to guard {qo}, and to return when you have triumphed.]",
  "quest.bar.offeredit2": "{ql} gazes reverently at {qo}, then back at you.\n\n\"You are its keeper now, and the time has come to resume your search\nfor the Amulet.  The Dungeons of Doom await your return through the\nmagic portal which brought you here.\"",
  "quest.bar.offeredit2.synopsis": "[\"You keep {qo}.  Return to The Dungeons of Doom to search for the Amulet.\"]",
  "quest.bar.othertime": "Again, and you think possibly for the last time, you approach\n{qH}.",
  "quest.bar.othertime.synopsis": "[Again, and you think possibly for the last time, you approach {qH}.]",
  "quest.bar.posthanks": "\"Tell us, {qp}, have you fared well on your great quest?\"",
  "quest.cav.assignquest": "\"You are indeed ready now, {qp}.  I shall tell you a tale of\ngreat suffering among your people:\n\n\"Shortly after you left on your vision quest, the caves were invaded by\nthe creatures sent against us by {qn}.\n\n\"She, herself, could not attack us due to her great size, but her minions\nhave harassed us ever since.  In the first attacks, many died, and the\nminions of {qn} managed to steal {qo}.\nThey took it to {qi} and there, none of our\n{qg} warriors have been able to go.\n\n\"You must find {qi}, and within it wrest\n{qo} from {qn}.  She guards it as\njealously as she guards all treasures she attains.  But with it,\nwe can make our caves safe once more.\n\n\"Please, {qp}, recover {qo} for us, and return it here.\"",
  "quest.cav.assignquest.synopsis": "[Find and defeat {qn}, recover {qo}, and return with it.]",
  "quest.cav.badalign": "\"{qp|C}!  You have deviated from my teachings.  You no longer follow\nthe path of the {qa} as you should.  I banish you from these caves, to\ngo forth and purify yourself.  Then, you might be able to accomplish this\nquest.\"",
  "quest.cav.badalign.synopsis": "[\"You no longer follow the path of the {qa}.  Go, and purify yourself.\"]",
  "quest.cav.badlevel": "\"Alas, {qp}, you are as yet too inexperienced to embark upon such\na difficult quest as that I propose to give you.\n\n\"{qr|An} could not possibly survive the rigors demanded to find\n{qi}, never mind to confront {qn} herself.\n\n\"Adventure some more, and you will learn the skills you will require.\n{qd} decrees it.\"",
  "quest.cav.badlevel.synopsis": "[\"{qr|An} is too inexperienced.  Come back when you have progressed.\"]",
  "quest.cav.discourage.1": "\"You are weak, {qc}.  No challenge for the Mother of all Dragons.\"",
  "quest.cav.discourage.2": "\"I grow hungry, {qr}.  You look like a nice appetizer!\"",
  "quest.cav.discourage.3": "\"Join me for lunch?  You're the main course, {qc}.\"",
  "quest.cav.discourage.4": "\"With {qo}, I am invincible!  You cannot succeed.\"",
  "quest.cav.discourage.5": "\"Your mentor, {ql} has failed.  You are nothing to fear.\"",
  "quest.cav.discourage.6": "\"You shall die here, {qc}.  {qr|An} cannot hope to defeat me.\"",
  "quest.cav.discourage.7": "\"You, a mere {qr} challenge the might of {qn}?  Hah!\"",
  "quest.cav.discourage.8": "\"I am the Mother of all Dragons!  You cannot hope to defeat me.\"",
  "quest.cav.discourage.9": "\"My claws are sharp now.  I shall rip you to shreds!\"",
  "quest.cav.discourage.10": "\"{qd} has deserted you, {qc}.  This is my domain.\"",
  "quest.cav.encourage.1": "\"{qn|C} is immune to her own breath weapons. You should use magic upon her that she does not use herself.\"",
  "quest.cav.encourage.2": "\"When you encounter {qn}, call upon {qd} for assistance.\"",
  "quest.cav.encourage.3": "\"There will be nowhere to hide inside {qn|s} inner sanctum.\"",
  "quest.cav.encourage.4": "\"Your best chance with {qn} will be to keep moving.\"",
  "quest.cav.encourage.5": "\"Do not be distracted by the great treasures in {qn|s} lair. Concentrate on {qo}.\"",
  "quest.cav.encourage.6": "\"{qo|C} is the only object that {qn} truly fears.\"",
  "quest.cav.encourage.7": "\"Do not be fooled by {qn|s} size.  She is fast, and it is rumored that she uses magic.\"",
  "quest.cav.encourage.8": "\"I would send a party of {qg|Plural} with you, but we will need all of our strength to defend ourselves.\"",
  "quest.cav.encourage.9": "\"Remember, be {qa} at all times.  This is your strength.\"",
  "quest.cav.encourage.10": "\"If only we had an amulet of reflection, this would not have happened.\"",
  "quest.cav.firsttime": "You descend through a barely familiar stairwell that you remember\n{ql} showing you when you embarked upon your vision quest.\n\nYou arrive back at {qH}, but something seems\nwrong here.  The usual smoke and glowing light of the fires of the\nouter caves are absent, and an uneasy quiet fills the damp air.",
  "quest.cav.firsttime.synopsis": "[You arrive back at {qH}, but something is wrong here.]",
  "quest.cav.goal_first": "You find yourself in a large cavern, with neatly polished walls, that\nnevertheless show signs of being scorched by fire.\n\nBones litter the floor, and there are objects scattered everywhere.\nThe air is close with the stench of sulphurous fumes.\n\n{qn|C} is clearly visible, but {qn_he} seems to be asleep.",
  "quest.cav.goal_first.synopsis": "[You enter a large cavern.  {qn|C} is present.]",
  "quest.cav.goal_next": "Once again, you find yourself in the lair of {qn}.",
  "quest.cav.gotit": "As you pick up {qo} it seems heavy at first, but as you\nhold it strength flows into your arms.\n\nYou suddenly feel full of power, as if nothing could possibly stand\nin your path.",
  "quest.cav.gotit.synopsis": "[{qo|C} fills you with a feeling of power.]",
  "quest.cav.guardtalk_after.1": "\"The rains have returned and the land grows lush again.\"",
  "quest.cav.guardtalk_after.2": "\"Peace has returned, give thanks to {qd}!\"",
  "quest.cav.guardtalk_after.3": "\"Welcome back!  Did you find {qo}?\"",
  "quest.cav.guardtalk_after.4": "\"So, {qp}, tell us the story of your fight with {qn}.\"",
  "quest.cav.guardtalk_after.5": "\"{ql|C} grows old.  Perhaps you will guide us after he ascends.\"",
  "quest.cav.guardtalk_before.1": "\"We have not been able to gather as much food since the Giants sealed off our access to the outer world.\"",
  "quest.cav.guardtalk_before.2": "\"Since {qn} sent her minions, we have been constantly fighting.\"",
  "quest.cav.guardtalk_before.3": "\"I have heard your vision quest was successful.  Is this so?\"",
  "quest.cav.guardtalk_before.4": "\"So, tell me, {qp}, how have you fared?\"",
  "quest.cav.guardtalk_before.5": "\"{ql|C} grows old.  We know not who will guide us after he ascends.\"",
  "quest.cav.hasamulet": "\"You have been successful, I see, {qp}.\n\n\"Now that the Amulet of Yendor is yours, here is what you must do:\n\n\"Journey upwards to the open air.  The Amulet you carry will then\ntake you into the Astral Planes, where the Great Temple of {qd}\ncasts its influence throughout our world.\n\n\"Sacrifice the Amulet on the altar.  Thus shall {qd} become supreme!\"",
  "quest.cav.hasamulet.synopsis": "[\"Take the Amulet to the altar of {qd} on the Astral Plane and offer it.\"]",
  "quest.cav.killed_nemesis": "{qn|C} sinks to the ground, her heads flailing about.\nAs she dies, a cloud of noxious fumes billows about her.",
  "quest.cav.killed_nemesis.synopsis": "[{qn|C} sinks to the ground, her heads flailing about. As she dies, a cloud of noxious fumes billows about her.]",
  "quest.cav.leader_first": "\"You have returned from your vision quest, {qp}.  Thank {qd}.\n\n\"We are in dire need of your help, my {qS}.\n\n\"But first, I must see if you are yet capable of the quest I would\nask you to undertake.\"",
  "quest.cav.leader_first.synopsis": "[\"You have returned.  We are in dire need of your help.\"]",
  "quest.cav.leader_last": "\"{qp|C}!  You have sealed our fate.  You seem unable to reform yourself,\nso I must select another to take your place.\n\n\"Begone from {qH}!  You have betrayed us by choosing\nthe path of the chaotic over the true path of the lawful.\n\n\"You no longer live in our eyes.\"",
  "quest.cav.leader_last.synopsis": "[\"You have betrayed the lawful.  Begone!\"]",
  "quest.cav.leader_next": "\"Again, you return to us, {qp}.  Let me see if you are ready now.\"",
  "quest.cav.leader_other": "\"Ah, {qp}.  Are you finally ready?\"",
  "quest.cav.locate_first": "You {qx} many large claw marks on the ground.  The tunnels ahead\nof you are larger than most of those in any cave complex you have\never been in before.\n\nYour nose detects the smell of carrion from within, and bones litter\nthe sides of the tunnels.",
  "quest.cav.locate_first.synopsis": "[You {qx} many large claw marks, smell carrion, and notice bones.]",
  "quest.cav.locate_next": "Once again, you approach {qi}.",
  "quest.cav.nemesis_first": "\"So, follower of {ql}, you seek to invade the lair of\n{qn}.  Only my meals are allowed down here.  Prepare\nto be eaten!\"",
  "quest.cav.nemesis_first.synopsis": "[{qn|C} threatens to eat you.]",
  "quest.cav.nemesis_next": "\"So, again you face me, {qc}.  No one has ever before escaped me.\nNow I shall kill you.\"",
  "quest.cav.nemesis_next.synopsis": "[\"So, again you face me, {qc}.  No one has ever before escaped me. Now I shall kill you.\"]",
  "quest.cav.nemesis_other": "\"You are getting annoying, {qc}.  Prepare to die.\"",
  "quest.cav.nemesis_wantsit": "\"I'll have {qo} from you, {qc}.  You shall die.\"",
  "quest.cav.nexttime": "Once again, you arrive back at {qH}.",
  "quest.cav.offeredit": "{ql|C} glimpses {qo} in your possession.\nHe smiles and says:\n\n    You have done it!  We are saved.  But I fear that {qo}\n    will always be a target for chaotic forces who will want it for their\n    own.\n\n    To prevent further trouble, I would like you, {qp},\n    to take {qo} away with you.  It will help you as you\n    quest for the Amulet of Yendor.",
  "quest.cav.offeredit.synopsis": "[\"Take {qo} with you.  It will help in your quest for the Amulet of Yendor.\"]",
  "quest.cav.offeredit2": "{ql} grasps {qo} proudly for a moment, then looks at you.\n\n\"You are its keeper now, and the time has come to resume your search\nfor the Amulet.  The Dungeons of Doom await your return through the\nmagic portal which brought you here.\"",
  "quest.cav.offeredit2.synopsis": "[\"You are the keeper of {qo} now.  Return to The Dungeons of Doom to search for the Amulet.]",
  "quest.cav.othertime": "For some reason, you think that this may be the last time you will\nenter {qH}.",
  "quest.cav.othertime.synopsis": "[For some reason, you think that this may be the last time you will enter {qH}.]",
  "quest.cav.posthanks": "\"{qp|C}!  Welcome back.\nHow goes your quest to recover the Amulet for {qd}?\"",
  "quest.cav.posthanks.synopsis": "[\"{qp|C}!  Welcome back. How goes your quest to recover the Amulet for {qd}?\"]",
  "quest.hea.assignquest": "For the first time, you sense a smile on {ql|s} face.\n\n    \"You have indeed learned as much as we can teach you in preparation\n    for this task.  Let me tell you what I know of the symptoms and hope\n    that you can provide a cure.\n\n    \"A short while ago, the dreaded {qn|t} was fooled by the gods\n    into thinking that {qn_he} could use {qo} to find a\n    cure for old age.  Think of it, eternal youth!  But {qn_his} good\n    health is accomplished by drawing the health from those around {qn_him}.\n\n    \"He has exhausted {qn_his} own supply of healthy people and now {qn_he} seeks to\n    extend {qn_his} influence into our world.  You must recover from {qn_him}\n    {qo} and break the spell.\n\n    \"You must travel into the swamps to {qi}, and from there\n    follow the trail to {qn|s} island lair.  Be careful.\"",
  "quest.hea.assignquest.synopsis": "[Travel to {qi} on your way to recover {qo} from {qn}.]",
  "quest.hea.badalign": "\"You have learned much of the remedies that benefit, but you must also\nknow which physic for which ail.  That is why {qd|s} teachings are a\npart of your training.\n\n\"Return to us when you have healed thyself.\"",
  "quest.hea.badalign.synopsis": "[Return when you are more {qa}.]",
  "quest.hea.badlevel": "\"Alas, {qp}, you are yet too inexperienced to deal with the rigors\nof such a task.  You must be able to draw on the knowledge of botany,\nalchemy and veterinary practices before I can send you on this quest \nwith good conscience.\n\n\"Return when you wear {qR|an}'s caduceus.\"",
  "quest.hea.badlevel.synopsis": "[You are too inexperienced.  Return when you are {qR|an}.]",
  "quest.hea.discourage.1": "\"They might as well give scalpels to wizards as to let you try to use {qo}!\"",
  "quest.hea.discourage.2": "\"If I could strike {ql}, surrounded by {ql_his} {qg|Plural}, imagine what I can do to you here by yourself.\"",
  "quest.hea.discourage.3": "\"I will put my {qR|plural} to work making a physic out of your ashes.\"",
  "quest.hea.discourage.4": "\"As we speak, Hades gathers your patients to join you.\"",
  "quest.hea.discourage.5": "\"After I'm done with you, I'll destroy {ql} as well.\"",
  "quest.hea.discourage.6": "\"You will have to kill me if you ever hope to leave this place.\"",
  "quest.hea.discourage.7": "\"I will impale your head on my caduceus for all to see.\"",
  "quest.hea.discourage.8": "\"There is no materia medica in your sack which will cure you of me!\"",
  "quest.hea.discourage.9": "\"Do not fight too hard, I want your soul strong, not weakened!\"",
  "quest.hea.discourage.10": "\"You should have stopped studying at veterinary.\"",
  "quest.hea.encourage.1": "\"Remember, {qp}, to always wash your hands before operating.\"",
  "quest.hea.encourage.2": "\"{qn|C} has no real magic of {qn_his} own.  To this {qn_he} is vulnerable.\"",
  "quest.hea.encourage.3": "\"If you have been true to {qd}, you can draw on the power of {qo}.\"",
  "quest.hea.encourage.4": "\"Bring with you antidotes for poisons.\"",
  "quest.hea.encourage.5": "\"Remember this, {qn} can twist the powers of {qo} to hurt instead of heal.\"",
  "quest.hea.encourage.6": "\"I have sent for Chiron, but I am afraid he will come too late.\"",
  "quest.hea.encourage.7": "\"Maybe when you return the snakes will once again begin to shed.\"",
  "quest.hea.encourage.8": "\"The plague grows worse as we speak.  Hurry, {qp}!\"",
  "quest.hea.encourage.9": "\"Many times {qn} has caused trouble in these lands.  It is time that {qn_he} was eradicated like the diseases {qn_he} has caused.\"",
  "quest.hea.encourage.10": "\"With but one eye, {qn} should be easy to blind.  Remember this.\"",
  "quest.hea.firsttime": "What sorcery has brought you back to {qH}?  The smell\nof fresh funeral pyres tells you that something is amiss with the healing\npowers that used to practice here.\n\nNo rhizotomists are tending the materia medica gardens, and where are the\ncommon folk who used to come for the cures?\n\nYou know that you must quickly make your way to the collegium, and\n{ql|s} iatreion, and find out what has happened in your absence.",
  "quest.hea.firsttime.synopsis": "[You arrive back at {qH} and must find {ql}.]",
  "quest.hea.goal_first": "You stand within sight of the infamous Isle of {qn}.  Even\nthe words of {ql} had not prepared you for this.\n\nSteeling yourself against the wails of the ill that pierce your ears,\nyou hurry on your task.  Maybe with {qo} you can\nheal them on your return, but not now.",
  "quest.hea.goal_first.synopsis": "[You have reached the lair of {qn}.  Take {qo} away from {qn_him}.]",
  "quest.hea.goal_next": "Once again, you {qx} the Isle of {qn} in the distance.",
  "quest.hea.gotit": "As you pick up {qo}, you feel its healing begin to\nwarm your soul.  You curse Zeus for taking it from its rightful owner,\nbut at least you hope that {ql} can put it to good use once\nagain.",
  "quest.hea.gotit.synopsis": "[You feel the healing power of {qo} and should return it to {ql}.]",
  "quest.hea.guardtalk_after.1": "\"Did you read that new treatise on the therapeutic use of leeches?\"",
  "quest.hea.guardtalk_after.2": "\"Paint a red caduceus on your shield and monsters won't hit you.\"",
  "quest.hea.guardtalk_after.3": "\"How are you feeling?  Perhaps a good bleeding will improve your spirits.\"",
  "quest.hea.guardtalk_after.4": "\"Have you heard the absurd new theory that diseases are caused by microscopic organisms, and not ill humors?\"",
  "quest.hea.guardtalk_after.5": "\"I see that you bring {qo}, now you can cure this plague!\"",
  "quest.hea.guardtalk_before.1": "\"Did you read that new treatise on the therapeutic use of leeches?\"",
  "quest.hea.guardtalk_before.2": "\"Paint a red caduceus on your shield and monsters won't hit you.\"",
  "quest.hea.guardtalk_before.3": "\"I passed handwriting so they are demoting me a rank.\"",
  "quest.hea.guardtalk_before.4": "\"I've heard that even {ql} has not been able to cure Chiron.\"",
  "quest.hea.guardtalk_before.5": "\"We think {qn} has used {qn_his} alchemists, and {qo}, to unleash a new disease we call 'the cold' on Gehennom.\"",
  "quest.hea.hasamulet": "\"Ah, you have recovered the Amulet, {qp}.  Well done!\n\n\"Now, you should know that you must travel through the Elemental Planes\nto the Astral, and there return the Amulet to {qd}.  Go forth and\nmay our prayers be as a wind upon your back.\"",
  "quest.hea.hasamulet.synopsis": "[\"You have recovered the Amulet.  Travel to the Astral Plane and return it to {qd}.\"]",
  "quest.hea.killed_nemesis": "The battered body of {qn} slumps to the ground and gasps\nout one last curse:\n\n    \"You have defeated me, {qp}, but I shall have my revenge.\n    How, I shall not say, but this curse shall be like a cancer\n    on you.\"\n\nWith that {qn} dies.",
  "quest.hea.killed_nemesis.synopsis": "[{qn|C} curses you as {qn_he} dies.]",
  "quest.hea.leader_first": "Feebly, {ql} raises {ql_his} head to look at you.\n\n\"It is good to see you again, {qp}.  I see the concern in your\neyes, but do not worry for me.  I am not ready for Hades yet.  We have\nexhausted much of our healing powers holding off {qn}.\nI need your fresh strength to carry on our work.\n\n\"Come closer and let me lay hands on you, and determine if you have\nthe skills necessary to accomplish this mission.\"",
  "quest.hea.leader_first.synopsis": "[{ql} is weak from the struggle with {qn}.  {ql_he|C} wants to examine you.]",
  "quest.hea.leader_last": "\"You have failed us, {qp}.  You are a quack!  A charlatan!\n\n\"Hades will be happy to hear that you are once again practicing your\narts on the unsuspecting.\"",
  "quest.hea.leader_last.synopsis": "[You are a failure as a healer.]",
  "quest.hea.leader_next": "\"Again you return to me, {qp}.  I sense that each trip back\nthe pleurisy and maladies of our land begin to infect you.  Let us\nhope and pray to {qd} that you become ready for your task before\nyou fall victim to the bad humors.\"",
  "quest.hea.leader_next.synopsis": "[\"Again you return to me, {qp}.  I sense that each trip back the pleurisy and maladies of our land begin to infect you.  Let us hope and pray to {qd} that you become ready for your task before you fall victim to the bad humors.\"]",
  "quest.hea.leader_other": "\"Chiron has fallen, Hermes has fallen, what else must I tell you to\nimpress upon you the importance of your mission!  I hope that you\nhave come prepared this time.\"",
  "quest.hea.leader_other.synopsis": "[\"Chiron has fallen, Hermes has fallen, what else must I tell you to impress upon you the importance of your mission!  I hope that you have come prepared this time.\"]",
  "quest.hea.locate_first": "You stand before the entrance to {qi}.  Strange\nscratching noises come from within the building.\n\nThe swampy ground around you seems to stink with disease.",
  "quest.hea.locate_first.synopsis": "[You have reached {qi} but all is not well.]",
  "quest.hea.locate_next": "Once again you stand at the entrance to {qi}.",
  "quest.hea.nemesis_first": "\"They have made a mistake in sending you, {qp}.\n\n\"When I add your youth to mine, it will just make it easier for me\nto defeat {ql}.\"",
  "quest.hea.nemesis_first.synopsis": "[\"I will take your life, then defeat {ql}.\"]",
  "quest.hea.nemesis_next": "\"Unlike your patients, you seem to keep coming back, {qp}!\"",
  "quest.hea.nemesis_other": "\"Which would you like, {qp}?  Boils, pleurisy, convulsions?\"",
  "quest.hea.nemesis_wantsit": "\"I'll have {qo} back from you, {qr}.  You are\nnot going to live to escape this place.\"",
  "quest.hea.nemesis_wantsit.synopsis": "[\"I'll have {qo} back from you, {qr}.  You are not going to live to escape this place.\"]",
  "quest.hea.nexttime": "After your last experience you expected to be here, but you certainly\ndid not expect to see things so much worse.  This time you must succeed.",
  "quest.hea.nexttime.synopsis": "[After your last experience you expected to be here, but you certainly did not expect to see things so much worse.  This time you must succeed.]",
  "quest.hea.offeredit": "As soon as {ql} sees {qo} {ql_he} summons {ql_his}\n{qg|Plural}.\n\nGently, {ql} reaches out and touches {qo}.\nHe instructs each of the assembled to do the same.  When everyone\nhas finished {ql_he} speaks to you.\n\n    \"Now that we have been replenished we can defeat this plague.  You must\n    take {qo} with you and replenish the worlds you have\n    been called upon to travel next.  I wish you could ride Chiron to the\n    end of your journey, but I need him to help me spread the cure.  Go\n    now and continue your journey.\"",
  "quest.hea.offeredit.synopsis": "[{ql} touches {qo} and tells {ql_his} {qg|Plural} to do so too, then tells you to take it with you.]",
  "quest.hea.offeredit2": "{ql} cautiously handles {qo} while watching you.\n\n\"You are its keeper now, and the time has come to resume your search\nfor the Amulet.  The Dungeons of Doom await your return through the\nmagic portal which brought you here.\"",
  "quest.hea.offeredit2.synopsis": "[{ql} tells you to keep {qo} and return to The Dungeons of Doom to search for the Amulet.]",
  "quest.hea.othertime": "Again, you {qx} {qH} in the distance.\n\nThe smell of death and disease permeates the air.  You do not have\nto be {qR|an} to know that {qn} is on the verge of victory.",
  "quest.hea.othertime.synopsis": "[Again, you {qx} {qH} in the distance.  The smell of death and disease permeates the air.  You do not have to be {qR|an} to know that {qn} is on the verge of victory.]",
  "quest.hea.posthanks": "\"You have again returned to us, {qp}.  We have done well in your\nabsence, yes?  How fare you upon your quest for the Amulet?\"",
  "quest.hea.posthanks.synopsis": "[\"You have again returned to us, {qp}.  We have done well in your absence, yes?  How fare you upon your quest for the Amulet?\"]",
  "quest.kni.assignquest": "\"Ah, {qp}.  Thou art truly ready, as no {qc} before thee hath\nbeen.  Hear now Our words:\n\n\"As thou noticed as thou approached {qH}, a great battle hath\nbeen fought recently in these fields.  Know thou that Merlin himself\ncame to aid Us here as We battled the foul {qn}.  In the midst of that\nbattle, {qn} struck Merlin a great blow, felling him.  Then, as Our\nforces were pressed back, {qn} stole {qo}.\n\n\"We eventually turned the tide, but lost many {qc|Plural} in doing so.\nMerlin was taken off by his apprentice, but hath not recovered.  We have\nbeen told that so long as {qn} possesseth {qo},\nMerlin will not regain his health.\n\n\"We hereby charge thee with this most important of duties:\n\n\"Go forth from this place, to the fens, and there thou wilt find\n{qi}.  From there, thou must track down {qn}.  Destroy the\nbeast, and return to Us {qo}.  Only then can\nWe restore Merlin to health.\"",
  "quest.kni.assignquest.synopsis": "[Pass through {qi} to reach {qn}.  Destroy {qn_him} and return with {qo}.]",
  "quest.kni.badalign": "\"Thou dishonourest Us, {qp}!  Thou hast strayed from the path of\nchivalry! Go from Our presence and do penance.  Only when thou art again\npure mayst thou return hence.\"",
  "quest.kni.badalign.synopsis": "[Go and do penance.  Return when you are truly {qa}.]",
  "quest.kni.badlevel": "\"Verily, {qp}, thou hast done well.  That thou hast survived thus\nfar is a credit to thy valor, but thou art yet unprepared for\nthe demands required as Our Champion.  {qr|An}, no matter how\npure, could never hope to defeat the foul {qn}.\n\n\"Journey forth from this place, and hone thy skills.  Return to\nOur presence when thou hast attained the noble title of {qR}.\"",
  "quest.kni.badlevel.synopsis": "[You are not prepared to face {qn}.  Return when you are {qR|an}.]",
  "quest.kni.discourage.1": "\"A mere {qr} can never withstand me!\"",
  "quest.kni.discourage.2": "\"I shall kill thee now, and feast!\"",
  "quest.kni.discourage.3": "\"Puny {qc}.  What manner of death dost thou wish?\"",
  "quest.kni.discourage.4": "\"First thee, {qp}, then I shall feast upon {ql}.\"",
  "quest.kni.discourage.5": "\"Hah!  Thou hast failed, {qr}.  Now thou shalt die.\"",
  "quest.kni.discourage.6": "\"Die, {qc}.  Thou art as nothing against my might.\"",
  "quest.kni.discourage.7": "\"I shall suck the marrow from thy bones, {qc}.\"",
  "quest.kni.discourage.8": "\"Let's see...  Baked?  No.  Fried?  Nay.  Broiled?  Yea verily, that is the way I like my {qc} for dinner.\"",
  "quest.kni.discourage.9": "\"Thy strength waneth, {qp}.  The time of thy death draweth near.\"",
  "quest.kni.discourage.10": "\"Call upon thy precious {qd}, {qp}.  It shall not avail thee.\"",
  "quest.kni.encourage.1": "\"Remember, {qp}, follow always the path of {qd}.\"",
  "quest.kni.encourage.2": "\"Though {qn} is verily a mighty foe, We have confidence in thy victory.\"",
  "quest.kni.encourage.3": "\"Beware, for {qn} hath surrounded {qn_him}self with hordes of foul creatures.\"",
  "quest.kni.encourage.4": "\"Great treasure, 'tis said, is hoarded in the lair of {qn}.\"",
  "quest.kni.encourage.5": "\"If thou possessest {qo}, {qp}, {qn|s} magic shall therewith be thwarted.\"",
  "quest.kni.encourage.6": "\"The gates of {qi} are guarded by forces unseen, {qp}. Go carefully.\"",
  "quest.kni.encourage.7": "\"Return {qo} to Us quickly, {qp}.\"",
  "quest.kni.encourage.8": "\"Destroy {qn}, {qp}, else {qH} shall surely fall.\"",
  "quest.kni.encourage.9": "\"Call upon {qd} when thou art in need.\"",
  "quest.kni.encourage.10": "\"To find {qi}, thou must keep thy heart pure.\"",
  "quest.kni.firsttime": "You materialize in the shadows of {qH}.  Immediately, you notice\nthat something is wrong.  The fields around the castle are trampled and\nwithered, as if some great battle has been recently fought.\n\nExploring further, you {qx} long gouges in the walls of {qH}.\nYou know of only one creature that makes those kinds of marks...",
  "quest.kni.firsttime.synopsis": "[Signs of battle include long gouges in the walls of {qH}.]",
  "quest.kni.goal_first": "As you exit the swamps, you {qx} before you a huge, gaping hole in the\nside of a hill.  From within, you smell the foul stench of carrion.\n\nThe pools on either side of the entrance are fouled with blood, and\npieces of rusted metal and broken weapons show above the surface.",
  "quest.kni.goal_first.synopsis": "[You {qx} the entrance to a cavern inside a hill.]",
  "quest.kni.goal_next": "Again, you stand at the entrance to {qn|s} lair.",
  "quest.kni.gotit": "As you pick up {qo}, you feel its protective fields\nform around your body.  You also feel a faint stirring in your mind, as\nif you are in two places at once, and in the second, you are waking from\na long sleep.",
  "quest.kni.gotit.synopsis": "[You feel the magic of {qo}.]",
  "quest.kni.guardtalk_after.1": "\"Hail, {qp}!  Verily, thou lookest well.\"",
  "quest.kni.guardtalk_after.2": "\"So, {qp}, didst thou find {qn} in the fens near {qi}?\"",
  "quest.kni.guardtalk_after.3": "\"Worthy {qp}, hast thou proven thy right purpose on the body of {qn}?\"",
  "quest.kni.guardtalk_after.4": "\"Verily, {ql} could have no better champion, {qp}.\"",
  "quest.kni.guardtalk_after.5": "\"Hast thou indeed recovered {qo}?\"",
  "quest.kni.guardtalk_before.1": "\"Hail, {qp}!  Verily, thou lookest well.\"",
  "quest.kni.guardtalk_before.2": "\"There is word, {qp}, that {qn} hath been sighted in the fens near {qi}.\"",
  "quest.kni.guardtalk_before.3": "\"Thou art our only hope now, {qp}.\"",
  "quest.kni.guardtalk_before.4": "\"Verily, {ql} could have no better champion, {qp}.\"",
  "quest.kni.guardtalk_before.5": "\"Many brave {qc|Plural} died when {qn} attacked.\"",
  "quest.kni.hasamulet": "\"Thou hast succeeded, We see, {qp}!  Now thou art commanded to take\nthe Amulet to be sacrificed to {qd} in the Plane of the Astral.\n\n\"Merlin hath counseled Us that thou must travel always upwards through\nthe Planes of the Elements, to achieve this goal.\n\n\"Go with {qd}, {qp}.\"",
  "quest.kni.hasamulet.synopsis": "[Take the Amulet to the Astral Plane and deliver it to {qd}.]",
  "quest.kni.killed_nemesis": "As {qn} sinks to the ground, blood gushing from {qn_his} open mouth, {qn_he}\ndefiantly curses you and {ql}:\n\n    \"Thou hast not won yet, {qr}.  By the gods, I shall return\n    and dog thy steps to the grave!\"\n\n{qn_his|C} tail flailing madly, {qn} tries to crawl towards you, but slumps\nto the ground and dies in a pool of {qn_his} own blood.",
  "quest.kni.killed_nemesis.synopsis": "[{qn|C} curses you as {qn_he} dies.]",
  "quest.kni.leader_first": "\"Ah, {qp}.  We see thou hast received Our summons.\nWe are in dire need of thy prowess.  But first, We must needs\ndecide if thou art ready for this great undertaking.\"",
  "quest.kni.leader_first.synopsis": "[{ql|C} checks whether you are ready for a great undertaking.]",
  "quest.kni.leader_last": "\"Thou disgracest this noble court with thine impure presence.  We have been\nlenient with thee, but no more.  Thy name shall be spoken no more.  We\nhereby strip thee of thy title, thy lands, and thy standing as {qc|an}.\nBegone from Our sight!\"",
  "quest.kni.leader_last.synopsis": "[You are a disgrace as {qc|an}.]",
  "quest.kni.leader_next": "\"Welcome again, {qp}.  We hope thou art ready now.\"",
  "quest.kni.leader_other": "\"Once again, thou standest before Us, {qp}.  Art thou ready now?\"",
  "quest.kni.locate_first": "You stand at the foot of {qi}.  Atop, you can {qx} a shrine.\nStrange energies seem to be focused here, and the hair on the back of\nyour neck stands on end.",
  "quest.kni.locate_first.synopsis": "[You have reached {qi} and can {qx} a shrine.]",
  "quest.kni.locate_next": "Again, you stand at the foot of {qi}.",
  "quest.kni.nemesis_first": "\"Hah!  Another puny {qc} seeks death.  I shall dine well tonight,\nthen tomorrow, {qH} shall fall!\"",
  "quest.kni.nemesis_first.synopsis": "[{qn|C} taunts you and issues a threat against {qH}.]",
  "quest.kni.nemesis_next": "\"Again, thou challengest me, {qr}?  So be it.  Thou wilt die here.\"",
  "quest.kni.nemesis_other": "\"Thou art truly foolish, {qr}.  I shall dispatch thee anon.\"",
  "quest.kni.nemesis_wantsit": "\"So, thou darest touch MY property!  I shall have that bauble back,\npuny {qr}.  Thou wilt die in agony!\"",
  "quest.kni.nemesis_wantsit.synopsis": "[\"So, thou darest touch MY property!  I shall have that bauble back, puny {qr}.  Thou wilt die in agony!\"]",
  "quest.kni.nexttime": "Once again you stand in the shadows of {qH}.",
  "quest.kni.offeredit": "As you approach {ql}, {ql_he} beams at you and says:\n\n    \"Well done!  Thou art truly the Champion of {qH}.  We\n    have received word that Merlin is recovering, and shall soon\n    rejoin Us.\n\n    \"He hath instructed Us that thou art now to be the guardian of\n    {qo}.  He feeleth that thou mayst have need of\n    its powers in thine adventures.  It is Our wish that thou keepest\n    {qo} with thee as thou searchest for the fabled\n    Amulet of Yendor.\"",
  "quest.kni.offeredit.synopsis": "[{qo|C} is yours now.  It will aid in your search for the Amulet.]",
  "quest.kni.offeredit2": "\"Careful, {qp}!  {qo|C} might break, and that would\nbe a tragic loss.  Thou art its keeper now, and the time hath come\nto resume thy search for the Amulet.  The Dungeons of Doom await thy\nreturn through the magic portal that brought thee here.\"",
  "quest.kni.offeredit2.synopsis": "[You are the keeper of {qo}.  Return to The Dungeons of Doom and find the Amulet.]",
  "quest.kni.othertime": "Again, you stand before {qH}.  You vaguely sense that this\nmay be the last time you stand before {ql}.",
  "quest.kni.othertime.synopsis": "[Again, you stand before {qH}.  You vaguely sense that this may be the last time you stand before {ql}.]",
  "quest.kni.posthanks": "\"Well met, {qp}.  How goeth thy search for the Amulet of Yendor?\"",
  "quest.mon.assignquest": "\"Yes, {qp}.  You are truly ready now.  Attend to me and I shall\ntell you of what has transpired:\n\n\"During one of the Great Meditations a short time ago, {qn} and\na legion of elementals invaded {qH}.  Many {qg|Plural}\nwere killed, including the one bearing {qo}.\n\nNow, there are barely enough {qg|Plural} left to keep the elementals\nat bay.\n\n\"We need you to find {qi}, then, from there,\ntravel to {qn|s} lair.  If you can manage to defeat {qn} and\nreturn {qo} here, we can then drive off the legions\nof elementals that slay our students.\n\n\"Go with {qd} as your guide, {qp}.\"",
  "quest.mon.assignquest.synopsis": "[Find {qi}, then continue to {qn|s} lair.  Defeat {qn_him} and return with {qo}.]",
  "quest.mon.badalign": "\"This is terrible, {qp}.  You have deviated from the true path!\nYou know that {qd} requires the most strident devotion of this\norder.  The {qs}hood must stand for utmost piety.\n\n\"Go from here, atone for your sins against {qd}.  Return only when\nyou have purified yourself.\"",
  "quest.mon.badalign.synopsis": "[You must atone.  Come back when you are worthy of {qd}.]",
  "quest.mon.badlevel": "\"Alas, {qp}, it is not yet to be.  A mere {qr} could never\nwithstand the might of {qn}.  Go forth, again into the world, and\nreturn when you have attained the post of {qR}.\"",
  "quest.mon.badlevel.synopsis": "[You are not ready to face {qn}.  Come back when you are {qR|an}.]",
  "quest.mon.discourage.1": "\"Submit to my will, {qc}, and I shall spare you.\"",
  "quest.mon.discourage.2": "\"Your puny powers are no match for me, {qc}.\"",
  "quest.mon.discourage.3": "\"I shall have you turned into a zombie for my pleasure!\"",
  "quest.mon.discourage.4": "\"Despair now, {qr}.  {qd} cannot help you.\"",
  "quest.mon.discourage.5": "\"I shall feast upon your soul for many days, {qc}.\"",
  "quest.mon.discourage.6": "\"Your death will be slow and painful.  That I promise!\"",
  "quest.mon.discourage.7": "\"You cannot defeat {qn}, you fool.  I shall kill you now.\"",
  "quest.mon.discourage.8": "\"Your precious {ql|t} will be my next victim.\"",
  "quest.mon.discourage.9": "\"I feel your powers failing you, {qr}.  You shall die now.\"",
  "quest.mon.discourage.10": "\"With {qo}, nothing can stand in my way.\"",
  "quest.mon.encourage.1": "\"You can prevail, if you rely on {qd}.\"",
  "quest.mon.encourage.2": "\"Remember that {qn} has great magic at his command.\"",
  "quest.mon.encourage.3": "\"Be pure, my {qS}.\"",
  "quest.mon.encourage.4": "\"Beware, {qi} is surrounded by hordes of earth elementals.\"",
  "quest.mon.encourage.5": "\"Remember your studies, and you will prevail!\"",
  "quest.mon.encourage.6": "\"Acquire and wear {qo} if you can.  They will aid you against {qn}.\"",
  "quest.mon.encourage.7": "\"Call upon {qd} when your need is greatest.  You will be answered.\"",
  "quest.mon.encourage.8": "\"Remember to use the elementals' strength against them!\"",
  "quest.mon.encourage.9": "\"Do not lose faith, {qp}.  If you do so, {qn} will grow stronger.\"",
  "quest.mon.encourage.10": "\"Wear {qo}.  They will assist you in your efforts.\"",
  "quest.mon.firsttime": "You find yourself standing in sight of {qH}.\nSomething is obviously wrong here.  Strange shapes lumber around\noutside {qH}!\n\nYou realize that {ql} needs your assistance!",
  "quest.mon.firsttime.synopsis": "[You have reached {qH} but something is wrong.  {ql|C} needs your aid.]",
  "quest.mon.goal_first": "The stench of brimstone is all about you, and the elementals close in\nfrom all sides!\n\nAhead, there is a small clearing amidst the bubbling pits of lava...",
  "quest.mon.goal_first.synopsis": "[You are surrounded by brimstone, lava, and elementals.]",
  "quest.mon.goal_next": "Again, you have invaded {qn|s} domain.",
  "quest.mon.gotit": "As you pick up {qo}, you feel the essence of\n{qd} fill your soul.  You know now why {qn} stole {qo_him} from\n{qH}, for with {qo_him}, {qc|an} of {qd} could\neasily defeat his plans.\n\nYou sense a message from {qd}.  Though not verbal, you\nget the impression that you must return to {ql} as soon\nas possible.",
  "quest.mon.gotit.synopsis": "[You feel the essence of {qd} and realize that you should take {qo} to {ql}.]",
  "quest.mon.guardtalk_after.1": "\"Greetings, honorable {qr}.  It is good to see you again.\"",
  "quest.mon.guardtalk_after.2": "\"Ah, {qp}!  Our deepest gratitude for all of your help.\"",
  "quest.mon.guardtalk_after.3": "\"Greetings, {qs}.  Perhaps you will take some time to meditate with us?\"",
  "quest.mon.guardtalk_after.4": "\"With this test behind you, may {qd} bring you enlightenment.\"",
  "quest.mon.guardtalk_after.5": "\"May {qd} be with you, {qs}.\"",
  "quest.mon.guardtalk_before.1": "\"Greetings, honorable {qr}.  It is good to see you.\"",
  "quest.mon.guardtalk_before.2": "\"Ah, {qp}!  Surely you can help us in our hour of need.\"",
  "quest.mon.guardtalk_before.3": "\"Greetings, {qs}.  {ql|C} has great need of your help.\"",
  "quest.mon.guardtalk_before.4": "\"Alas, it seems as if even {qd} has deserted us.\"",
  "quest.mon.guardtalk_before.5": "\"May {qd} be with you, {qs}.\"",
  "quest.mon.hasamulet": "\"You have prevailed, {qp}!  {qd} is surely with you.  Now,\nyou must take the Amulet, and sacrifice it on {qd|s} altar on\nthe Astral Plane.  I suspect that I shall never see you again in this\nlife, but I hope to at {qd|s} feet.\"",
  "quest.mon.hasamulet.synopsis": "[Take the Amulet to the Astral Plane and deliver it to {qd}.]",
  "quest.mon.killed_nemesis": "{qn|C} gasps:\n\n    \"You have only defeated this mortal body.  Know this: my spirit\n    is strong.  I shall return and reclaim what is mine!\"\n\nWith that, {qn} expires.",
  "quest.mon.killed_nemesis.synopsis": "[As {qn} dies, {qn_he} threatens to return.]",
  "quest.mon.leader_first": "\"Ah, {qp}, my {qS}.  You have returned to us at last.\nA great blow has befallen our order; perhaps you can help us.\nFirst, however, I must determine if you are prepared for this\ngreat challenge.\"",
  "quest.mon.leader_first.synopsis": "[{ql|C} checks whether you are ready for the great challenge.]",
  "quest.mon.leader_last": "\"You are a heretic, {qp}!  How can you, {qr|an}, deviate so from the\nteachings of {qd}?  Begone from this temple.  You are no longer\n{qs|an} to this order.  We will pray to {qd} for other assistance,\nas you have failed us utterly.\"",
  "quest.mon.leader_last.synopsis": "[You are a heretic and have failed utterly.]",
  "quest.mon.leader_next": "\"Again, my {qS}, you stand before me.  Are you ready now to help us?\"",
  "quest.mon.leader_other": "\"Once more, {qp}, you stand within the sanctum.  Are you ready now?\"",
  "quest.mon.locate_first": "You remember the descriptions of {qi}, given\nto you by {ql}.  It is ahead that you will find\n{qn}'s trail.",
  "quest.mon.locate_first.synopsis": "[You have reached {qi}.  {qn|C} lurks further ahead.]",
  "quest.mon.locate_next": "Again, you stand before {qi}.",
  "quest.mon.nemesis_first": "\"Ah, so {ql} has sent another {qg} to retrieve\n{qo}.\n\n\"No, I see you are no {qg}.  Perhaps I shall have some fun today\nafter all.  Prepare to die, {qr}!  You shall never regain\n{qo}.\"",
  "quest.mon.nemesis_first.synopsis": "[You are no {qg}.  You shall never regain {qo}.]",
  "quest.mon.nemesis_next": "\"So, {qr}.  Again you challenge me.\"",
  "quest.mon.nemesis_other": "\"Die now, {qr}.  {qd} has no power here to aid you.\"",
  "quest.mon.nemesis_wantsit": "\"You shall die, {qr}, and I will have {qo} back.\"",
  "quest.mon.nexttime": "Once again, you stand before {qH}.",
  "quest.mon.offeredit": "\"You have returned, {qp}.  And with {qo}, I see.\nCongratulations.\n\n\"I have been in meditation, and have received direction from\na minion of {qd}.  {qd} commands that you retain\n{qo}.  With {qo_him}, you must recover the Amulet\nof Yendor.\n\n\"Go forth, and let {qd} guide your steps.\"",
  "quest.mon.offeredit.synopsis": "[Keep {qo}.  {qo_he|C} will help you recover the Amulet of Yendor.]",
  "quest.mon.offeredit2": "{ql|C} studies {qo} for a moment,\nthen returns his gaze to you.\n\n\"{qo|C} must remain with you.  Use {qo_him}\nas you resume your search for the Amulet.\nThe Dungeons of Doom await your return through the magic portal\nthat brought you here.\"",
  "quest.mon.offeredit2.synopsis": "[Keep {qo} and return to The Dungeons of Doom to search for the Amulet.]",
  "quest.mon.othertime": "Again you face {qH}.  Your intuition hints that this\nmay be the final time you come here.",
  "quest.mon.othertime.synopsis": "[Again you face {qH}.  Your intuition hints that this may be the final time you come here.]",
  "quest.mon.posthanks": "\"Welcome back, {qp}.  How is your quest for the Amulet going?\"",
  "quest.pri.assignquest": "\"Yes, {qp}.  You are truly ready now.  Attend to me and I shall\ntell you of what has transpired:\n\n\"At one of the Great Festivals a short time ago, {qn} and a legion\nof undead invaded {qH}.  Many {qg|Plural} were killed, including\nthe one carrying {qo}.\n\n\"As a final act of vengefulness, {qn} desecrated the altar here.\nWithout it, we could not mount a counter-attack.  Now, there are\nbarely enough {qg|Plural} left to keep the undead at bay.\n\n\"We need you to find {qi}, then, from there, travel\nto {qn|s} lair.  If you can manage to defeat {qn} and return\n{qo} here, we can then drive off the legions of\nundead that befoul the land.\n\n\"Go with {qd} as your guide, {qp}.\"",
  "quest.pri.assignquest.synopsis": "[{qn|C} invaded {qH} and captured {qo}.  Defeat {qn_him} and retrieve {qo_he}.]",
  "quest.pri.badalign": "\"This is terrible, {qp}.  You have deviated from the true path!\nYou know that {qd} requires the most strident devotion of this\norder.  The {qs}hood must stand for utmost piety.\n\n\"Go from here, atone for your sins against {qd}.  Return only when\nyou have purified yourself.\"",
  "quest.pri.badalign.synopsis": "[You have deviated from the path.  Return when you have purified yourself.]",
  "quest.pri.badlevel": "\"Alas, {qp}, it is not yet to be.  A mere {qr} could never\nwithstand the might of {qn}.  Go forth, again into the world, and return\nwhen you have attained the post of {qR}.\"",
  "quest.pri.badlevel.synopsis": "[{qr|An} cannot withstand {qn}.  Come back when you are {qR|an}.]",
  "quest.pri.discourage.1": "\"Submit to my will, {qc}, and I shall spare you.\"",
  "quest.pri.discourage.2": "\"Your puny powers are no match for me, {qc}.\"",
  "quest.pri.discourage.3": "\"I shall have you turned into a zombie for my pleasure!\"",
  "quest.pri.discourage.4": "\"Despair now, {qr}.  {qd} cannot help you.\"",
  "quest.pri.discourage.5": "\"I shall feast upon your soul for many days, {qc}.\"",
  "quest.pri.discourage.6": "\"Your death will be slow and painful.  That I promise!\"",
  "quest.pri.discourage.7": "\"You cannot defeat {qn}, you fool.  I shall kill you now.\"",
  "quest.pri.discourage.8": "\"Your precious {ql|t} will be my next victim.\"",
  "quest.pri.discourage.9": "\"I feel your powers failing you, {qr}.  You shall die now.\"",
  "quest.pri.discourage.10": "\"With {qo}, nothing can stand in my way.\"",
  "quest.pri.encourage.1": "\"You can prevail, if you rely on {qd}.\"",
  "quest.pri.encourage.2": "\"Remember that {qn} has great magic at his command.\"",
  "quest.pri.encourage.3": "\"Be pure, my {qS}.\"",
  "quest.pri.encourage.4": "\"Beware, {qi} is surrounded by a great graveyard.\"",
  "quest.pri.encourage.5": "\"You may be able to affect {qn} with magical cold.\"",
  "quest.pri.encourage.6": "\"Acquire and wear {qo} if you can.  It will aid you against {qn}.\"",
  "quest.pri.encourage.7": "\"Call upon {qd} when your need is greatest.  You will be answered.\"",
  "quest.pri.encourage.8": "\"The undead legions are weakest during the daylight hours.\"",
  "quest.pri.encourage.9": "\"Do not lose faith, {qp}.  If you do so, {qn} will grow stronger.\"",
  "quest.pri.encourage.10": "\"Wear {qo}.  It will assist you against the undead.\"",
  "quest.pri.firsttime": "You find yourself standing in sight of {qH}.  Something\nis obviously wrong here.  The doors to {qH}, which usually\nstand open, are closed.  Strange human shapes shamble around\noutside.\n\nYou realize that {ql} needs your assistance!",
  "quest.pri.firsttime.synopsis": "[You are at {qH}; the doors are closed.  {ql|C} needs your help!]",
  "quest.pri.goal_first": "The stench of brimstone is all about you, and the shrieks and moans\nof tortured souls assault your psyche.\n\nAhead, there is a small clearing amidst the bubbling pits of lava...",
  "quest.pri.goal_first.synopsis": "[The stench of brimstone surrounds you, the shrieks and moans are endless.]",
  "quest.pri.goal_next": "Again, you have invaded {qn|s} domain.",
  "quest.pri.gotit": "As you pick up {qo}, you feel the essence of\n{qd} fill your soul.  You know now why {qn} stole it from\n{qH}, for with it, {qc|an} of {qd} could\neasily defeat his plans.\n\nYou sense a message from {qd}.  Though not verbal, you\nget the impression that you must return to {ql} as soon\nas possible.",
  "quest.pri.gotit.synopsis": "[You feel {qd} as you pick up {qo}; return {qo_he} to {ql}.]",
  "quest.pri.guardtalk_after.1": "\"Greetings, {qr}.  It is good to see you again.\"",
  "quest.pri.guardtalk_after.2": "\"Ah, {qp}!  Our deepest gratitude for all of your help.\"",
  "quest.pri.guardtalk_after.3": "\"Welcome back, {qs}!  With {qo}, no undead can stand against us.\"",
  "quest.pri.guardtalk_after.4": "\"Praise be to {qd}, for delivering us from {qn}.\"",
  "quest.pri.guardtalk_after.5": "\"May {qd} be with you, {qs}.\"",
  "quest.pri.guardtalk_before.1": "\"Greetings, honored {qr}.  It is good to see you.\"",
  "quest.pri.guardtalk_before.2": "\"Ah, {qp}!  Surely you can help us in our hour of need.\"",
  "quest.pri.guardtalk_before.3": "\"Greetings, {qs}.  {ql|C} has great need of your help.\"",
  "quest.pri.guardtalk_before.4": "\"Alas, it seems as if even {qd} has deserted us.\"",
  "quest.pri.guardtalk_before.5": "\"May {qd} be with you, {qs}.\"",
  "quest.pri.hasamulet": "\"You have prevailed, {qp}!  {qd} is surely with you.  Now,\nyou must take the amulet, and sacrifice it on {qd|s} altar on\nthe Astral Plane.  I suspect that I shall never see you again in this\nlife, but I hope to at {qd|s} feet.\"",
  "quest.pri.hasamulet.synopsis": "[Take the Amulet to the Astral Plane and offer it on {qd|s} altar.]",
  "quest.pri.killed_nemesis": "You feel a wrenching shift in the ether as {qn|s} body dissolves\ninto a cloud of noxious gas.\n\nSuddenly, a voice booms out:\n\n    \"Thou hast defeated the least of my minions, {qr}.\n    Know now that Moloch is aware of thy presence.\n    As for thee, {qn}, I shall deal with thy failure\n    at my leisure.\"\n\nYou then hear the voice of {qn}, screaming in terror...",
  "quest.pri.killed_nemesis.synopsis": "[{qn|C} dies.  Moloch is aware of you and angry at {qn}.]",
  "quest.pri.leader_first": "\"Ah, {qp}, my {qS}.  You have returned to us at last.\nA great blow has befallen our order; perhaps you can help us.\nFirst, however, I must determine if you are prepared for this\ngreat challenge.\"",
  "quest.pri.leader_first.synopsis": "[You have returned and we need your help.  Are you ready?]",
  "quest.pri.leader_last": "\"You are a heretic, {qp}!  How can you, {qr|an}, deviate so from the\nteachings of {qd}?  Begone from this temple.  You are no longer\n{qs|an} to this order.  We will pray to {qd} for other assistance,\nas you have failed us utterly.\"",
  "quest.pri.leader_last.synopsis": "[You are a heretic who has deviated from the teachings of {qd}.]",
  "quest.pri.leader_next": "\"Again, my {qS}, you stand before me.  Are you ready now to help us?\"",
  "quest.pri.leader_other": "\"Once more, {qp}, you stand within the sanctum.  Are you ready now?\"",
  "quest.pri.locate_first": "You stand facing a large graveyard.  The sky above is filled with clouds\nthat seem to get thicker closer to the center.  You sense the presence of\nundead in larger numbers than you have ever encountered before.\n\nYou remember the descriptions of {qi}, given to you by\n{ql}.  It is ahead that you will find {qn|s} trail.",
  "quest.pri.locate_first.synopsis": "[You have found {qi}.  The trail to {qn} lies ahead.]",
  "quest.pri.locate_next": "Again, you stand before {qi}.",
  "quest.pri.nemesis_first": "\"Ah, so {ql} has sent another {qg|C} to retrieve\n{qo}.\n\n\"No, I see you are no {qg|C}.  Perhaps I shall have some fun today\nafter all.  Prepare to die, {qr}!  You shall never regain\n{qo}.\"",
  "quest.pri.nemesis_first.synopsis": "[{ql|C} has sent you, but you are no {qg|C}.  I shall destroy you.]",
  "quest.pri.nemesis_next": "\"So, {qr}.  Again you challenge me.\"",
  "quest.pri.nemesis_other": "\"Die now, {qr}.  {qd} has no power here to aid you.\"",
  "quest.pri.nemesis_wantsit": "\"You shall die, {qr}, and I will have {qo} back.\"",
  "quest.pri.nexttime": "Once again, you stand before {qH}.",
  "quest.pri.offeredit": "\"You have returned, {qp}.  And with {qo}, I see.\nCongratulations.\n\n\"I have been in meditation, and have received direction from\na minion of {qd}.  {qd} commands that you retain\n{qo}.  With it, you must recover the Amulet\nof Yendor.\n\n\"Go forth, and let {qd} guide your steps.\"",
  "quest.pri.offeredit.synopsis": "[Congratulations, {qp}.  Keep {qo}; go and recover the Amulet.]",
  "quest.pri.offeredit2": "{ql|C} reiterates that {qo} is yours now.\n\n\"The time has come to resume your search for the Amulet.\nThe Dungeons of Doom await your return through the magic portal\nthat brought you here.\"",
  "quest.pri.offeredit2.synopsis": "[{qo|C} is yours now.  Return to The Dungeons of Doom and find the Amulet.]",
  "quest.pri.othertime": "Again you face {qH}.  Your intuition hints that this may be\nthe final time you come here.",
  "quest.pri.othertime.synopsis": "[Again you face {qH}.  Your intuition hints that this may be the final time you come here.]",
  "quest.pri.posthanks": "\"Welcome back, {qp}.  How is your quest for the Amulet going?\"",
  "quest.ran.assignquest": "\"You are indeed ready, {qp}.  I shall tell you what has transpired,\nand why we so desperately need your help:\n\n\"A short time ago, the mountain centaurs to the east invaded\nand enslaved the plains centaurs in this area.  The local\nleader is now only a figurehead, and serves {qn}.\n\n\"During our last gathering of worship here, we were beset by hordes of\nhostile centaurs, as you witnessed.  In the first onslaught a group,\nheaded by {qn} {qn_him}self, managed to breach the grove and steal\n{qo}.\n\n\"Since then, we have been besieged.  We do not know how much longer\nwe will be able to maintain our magical barriers.\n\n\"If we are to survive, you, {qp}, must infiltrate\n{qi}.  There, you will find a pathway down, to the\nunderground cavern of {qn}.  He has always coveted\n{qo}, and will surely keep it.\n\n\"Recover {qo} for us, {qp}!  Only then will {qd} be safe.\"",
  "quest.ran.assignquest.synopsis": "[{qn|C} has stolen {qo}.  Infiltrate {qi} and retrieve {qo_he} for us.]",
  "quest.ran.badalign": "\"You have strayed, {qp}!  You know that {qd} requires that\nwe maintain a pure devotion to things {qa}!\n\n\"You must go from us.  Return when you have purified yourself.\"",
  "quest.ran.badalign.synopsis": "[You are not sufficiently {qa}.  Come back when you have purified yourself.]",
  "quest.ran.badlevel": "\"{qp}, you are yet too inexperienced to withstand the demands of that\nwhich we need you to do.  {qR|An} might just be able to do this thing.\n\n\"Return to us when you have learned more, my {qS}.\"",
  "quest.ran.badlevel.synopsis": "[You are too inexperienced.  Come back when you are {qR|an}.]",
  "quest.ran.discourage.1": "\"Your {qd} is nothing, {qc}.  You are mine now!\"",
  "quest.ran.discourage.2": "\"Run away little {qc}!  You can never hope to defeat {qn}!\"",
  "quest.ran.discourage.3": "\"My servants will rip you to shreds!\"",
  "quest.ran.discourage.4": "\"I shall display your head as a trophy.  What do you think about that wall?\"",
  "quest.ran.discourage.5": "\"I shall break your {ql|s} grove, and destroy all the {qg|Plural}!\"",
  "quest.ran.discourage.6": "\"{qd} has abandoned you, {qc}.  You are doomed.\"",
  "quest.ran.discourage.7": "\"{qr|An}?  {ql|C} sends a mere {qr} against me?  Hah!\"",
  "quest.ran.discourage.8": "\"{ql|C} has failed, {qc}.  {qo|C} will never leave here.\"",
  "quest.ran.discourage.9": "\"You really think you can defeat me, eh {qc}?  You are wrong!\"",
  "quest.ran.discourage.10": "\"You weaken, {qc}.  I shall kill you now.\"",
  "quest.ran.encourage.1": "\"It is rumored that the Forest and Mountain Centaurs have resolved their ancient feud and now band together against us.\"",
  "quest.ran.encourage.2": "\"{qn|C} is strong, and very smart.\"",
  "quest.ran.encourage.3": "\"Use {qo}, when you find it.  It will help you survive to reach us.\"",
  "quest.ran.encourage.4": "\"Remember, let {qd} be your guide.\"",
  "quest.ran.encourage.5": "\"Call upon {qd} when you face {qn}. The very act of doing so will infuriate him, and give you advantage.\"",
  "quest.ran.encourage.6": "\"{qn} and his kind have always hated us.\"",
  "quest.ran.encourage.7": "\"We cannot hold the grove much longer, {qp}.  Hurry!\"",
  "quest.ran.encourage.8": "\"To infiltrate {qi}, you must be very stealthy.\"",
  "quest.ran.encourage.9": "\"Remember that {qn} is a braggart.  Trust not what he says.\"",
  "quest.ran.encourage.10": "\"You can triumph, {qp}, if you trust in {qd}.\"",
  "quest.ran.firsttime": "You arrive in familiar surroundings.  In the distance, you {qx} the\nancient forest grove, the place of worship to {qd}.\n\nSomething is wrong, though.  Surrounding the grove are centaurs!\nAnd they've noticed you!",
  "quest.ran.firsttime.synopsis": "[The ancient forest grove is surrounded by centaurs.]",
  "quest.ran.goal_first": "You descend into a weird place, in which roughly cut cave-like walls\njoin with smooth, finished ones, as if someone was in the midst of\nfinishing off the construction of a subterranean complex.\n\nOff in the distance, you hear a sound like the clattering of many\nhooves on rock.",
  "quest.ran.goal_first.synopsis": "[You descend into a subterranean complex.  Hooves clatter in the distance.]",
  "quest.ran.goal_next": "Once again, you enter the distorted castle of {qn}.",
  "quest.ran.gotit": "As you pick up {qo}, it seems to glow, and a warmth\nfills you completely.  You realize that its power is what has protected\nyour {qs|plural} against their enemies for so long.\n\nYou must now return it to {ql} without delay -- their lives depend\non your speed.",
  "quest.ran.gotit.synopsis": "[You pick up {qo} and feel power.  It's time to return {qo_he} to {ql}.]",
  "quest.ran.guardtalk_after.1": "\"{qp|C}!  I have not seen you in many moons.  How do you fare?\"",
  "quest.ran.guardtalk_after.2": "\"Birdsong has returned to the grove, surely this means you have defeated {qn}.\"",
  "quest.ran.guardtalk_after.3": "\"{ql|C} seems to have regained some of his strength.\"",
  "quest.ran.guardtalk_after.4": "\"So, tell us how you entered {qi}, in case some new evil arises there.\"",
  "quest.ran.guardtalk_after.5": "\"Is that truly {qo} that I see you carrying?\"",
  "quest.ran.guardtalk_before.1": "\"{qp|C}!  I have not seen you in many moons.  How do you fare?\"",
  "quest.ran.guardtalk_before.2": "\"{qn|C} continues to threaten the grove.  But we hold fast.\"",
  "quest.ran.guardtalk_before.3": "\"{ql|C} is growing weak.  The magic required to defend the grove drains us.\"",
  "quest.ran.guardtalk_before.4": "\"Remember {qi} is hard to enter.  Beware the distraction of leatherwings.\"",
  "quest.ran.guardtalk_before.5": "\"We must regain {qo}.  Without it we will be overrun.\"",
  "quest.ran.hasamulet": "\"You have it!  You have recovered the Amulet of Yendor!\nNow attend to me, {qp}, and I will tell you what must be done:\n\n\"The Amulet has within it magic, the capability to transport you to\nthe Astral Plane, where the primary circle of {qd} resides.\n\n\"To activate this magic, you must travel upwards as far as you can.\nWhen you reach the temple, sacrifice the Amulet to {qd}.\n\n\"Thus will you fulfill your destiny.\"",
  "quest.ran.hasamulet.synopsis": "[You have the Amulet!  Take it to the Astral Plane and offer it to {qd}.]",
  "quest.ran.killed_nemesis": "{qn|C} collapses to the ground, cursing you and {ql}, then says:\n\n    \"You have defeated me, {qr}!  But I curse you one final time, with\n    my dying breath!  You shall die before you leave my castle!\"",
  "quest.ran.killed_nemesis.synopsis": "[{qn|C} curses you as {qn_he} dies.]",
  "quest.ran.leader_first": "\"{qp|C}!  You have returned!  Thank {qd}.\n\n\"We have great need of you.  But first, I must see if you have the\nrequired abilities to take on this responsibility.\"",
  "quest.ran.leader_first.synopsis": "[You have returned, {qp}.  We need your help.  Are you ready?]",
  "quest.ran.leader_last": "\"{qp|C}!  You have doomed us all.  You fairly radiate lawful influences\nand weaken the power we have raised in this grove as a result!\n\n\"Begone!  We renounce your {qs}hood with us!  You are an outcast now!\"",
  "quest.ran.leader_last.synopsis": "[You are not sufficiently {qa}.  We renounce your {qs}hood.]",
  "quest.ran.leader_next": "\"Once again, {qp}, you stand in our midst.  Are you ready now?\"",
  "quest.ran.leader_other": "\"Ah, you are here again, {qp}.  Allow me to determine your readiness...\"",
  "quest.ran.locate_first": "This must be {qi}.\n\nYou are in a cave built of many different rooms, all interconnected\nby tunnels.  Your quest is to find and shoot the evil wumpus that\nresides elsewhere in the cave without running into any bottomless\npits or using up your limited supply of arrows.  Good luck.\n\nYou are in room 9 of the cave.  There are tunnels to rooms\n5, 8, and 10.\n*rustle* *rustle* (must be bats nearby.)\n*sniff* (I can smell the evil wumpus nearby!)",
  "quest.ran.locate_first.synopsis": "[This is {qi}.  There are bats nearby.  Beware the wumpus!]",
  "quest.ran.locate_next": "Once again, you descend into {qi}.\n\n*whoosh* (I feel a draft from some pits.)\n*rustle* *rustle* (must be bats nearby.)",
  "quest.ran.locate_next.synopsis": "[You are in {qi}.  There are pits.  There are bats nearby.]",
  "quest.ran.nemesis_first": "\"So, {qc}.  {ql|C} has sent you to recover {qo}.\n\n\"Well, I shall keep that bauble.  It pleases me.  You, {qc}, shall die.\"",
  "quest.ran.nemesis_first.synopsis": "[You have come to recover {qo}, but I shall keep {qo_he} and you shall die.]",
  "quest.ran.nemesis_next": "\"Back again, eh?  Well, a mere {qr} is no threat to me!  Die, {qc}!\"",
  "quest.ran.nemesis_other": "\"You haven't learned your lesson, {qc}.  You can't kill me!  You shall die now.\"",
  "quest.ran.nemesis_wantsit": "\"I shall have {qo} from you, {qr}.  Then I shall\nkill you.\"",
  "quest.ran.nemesis_wantsit.synopsis": "[\"I shall have {qo} from you, {qr}.  Then I shall kill you.\"]",
  "quest.ran.nexttime": "Once again, you stand before {qH}.",
  "quest.ran.offeredit": "\"{qp|C}!  You have succeeded!  I feared it was not possible!\n\n\"You have returned with {qo}!\n\n\"I fear, now, that the Centaurs will regroup and plot yet another raid.\nThis will take some time, but if you can recover the Amulet of Yendor\nfor {qd} before that happens, we will be eternally safe.\n\n\"Take {qo} with you.  It will aid in your quest for\nthe Amulet.\"",
  "quest.ran.offeredit.synopsis": "[You have succeeded.  Take {qo} with you as you go to find the Amulet.]",
  "quest.ran.offeredit2": "{ql} flexes {qo} reverently.\n\n\"With this wondrous bow, one need never run out of arrows.\nYou are its keeper now, and the time has come to resume your\nsearch for the Amulet.  The Dungeons of Doom await your return\nthrough the magic portal that brought you here.\"",
  "quest.ran.offeredit2.synopsis": "[You are the keeper of {qo} now.  Go and find the Amulet.]",
  "quest.ran.othertime": "You have the oddest feeling that this may be the last time you\nare to enter {qH}.",
  "quest.ran.othertime.synopsis": "[You have the oddest feeling that this may be the last time you are to enter {qH}.]",
  "quest.ran.posthanks": "\"Welcome, {qp}.  How have you fared on your quest for the Amulet\nof Yendor?\"",
  "quest.ran.posthanks.synopsis": "[\"Welcome, {qp}.  How have you fared on your quest for the Amulet of Yendor?\"]",
  "quest.rog.assignquest": "\"Will everyone not going to retrieve {qo} from that\njerk, {qn}, take one step backwards.  Good choice,\n{qp}, because I was going to send you anyway.  My other {qg|plural}\nare too valuable to me.\n\n\"Here's the deal.  I want {qo}, {qn}\nhas {qo}.  You are going to get {qo}\nand bring it back to me.  So simple an assignment even you can understand\nit.\"",
  "quest.rog.assignquest.synopsis": "[Get {qo} from {qn} and bring it to {ql}.]",
  "quest.rog.badalign": "\"Maybe I should chain you to my perch here for a while.  Perhaps watching\nreal {qa} men at work will bring some sense back to you.  I don't\nthink I could stand the sight of you for that long though.  Come back\nwhen you can be trusted to act properly.\"",
  "quest.rog.badalign.synopsis": "[Come back when you are really {qa}.]",
  "quest.rog.badlevel": "\"In the time that you've been gone you've only been able to master the\narts of {qr|an}?  I've trained ten times again as many {qR|plural}\nin that time.  Maybe I should send one of them, no?  Where would that\nleave you, {qp}?  Oh yeah, I remember, I was going to kill you!\"",
  "quest.rog.badlevel.synopsis": "[{qr|An} is not adequately trained to handle this job.]",
  "quest.rog.discourage.1": "\"May I suggest a compromise.  Are you interested in gold or gems?\"",
  "quest.rog.discourage.2": "\"Please don't force me to kill you.\"",
  "quest.rog.discourage.3": "\"Grim times are upon us all.  Will you not see reason?\"",
  "quest.rog.discourage.4": "\"I knew {ql}, and you're no {ql|t}, thankfully.\"",
  "quest.rog.discourage.5": "\"It is a shame that we are not meeting under more pleasant circumstances.\"",
  "quest.rog.discourage.6": "\"I was once like you are now, {qp}.  Believe in me -- our way is better.\"",
  "quest.rog.discourage.7": "\"Stay with me, and I will make you {qo|s} guardian.\"",
  "quest.rog.discourage.8": "\"When you return, with or without {qo}, {ql} will have you killed.\"",
  "quest.rog.discourage.9": "\"Do not be fooled; I am prepared to kill to defend {qo}.\"",
  "quest.rog.discourage.10": "\"I can reunite you with the Twain.  Oh, the stories you can swap.\"",
  "quest.rog.encourage.1": "\"You don't seem to understand, {qo} isn't here so neither should you be!\"",
  "quest.rog.encourage.2": "\"May {qd} curse you with lead fingers.  Get going!\"",
  "quest.rog.encourage.3": "\"We don't have all year.  GET GOING!\"",
  "quest.rog.encourage.4": "\"How would you like a scar necklace?  I'm just the jeweler to do it!\"",
  "quest.rog.encourage.5": "\"Lazy S.O.B.  Maybe I should call up someone else...\"",
  "quest.rog.encourage.6": "\"Maybe I should open your skull and see if my instructions are inside?\"",
  "quest.rog.encourage.7": "\"This is not a task you can complete in the afterlife, you know.\"",
  "quest.rog.encourage.8": "\"Inside every living person is a dead person trying to get out, and I have your key!\"",
  "quest.rog.encourage.9": "\"We're almost out of hell-hound chow, so why don't you just get moving!\"",
  "quest.rog.encourage.10": "\"You know, {qo} isn't going to come when you whistle.  You must get it yourself.\"",
  "quest.rog.firsttime": "Unexpectedly, you find yourself back in Ransmannsby, where you trained to\nbe a thief.  Quickly you make the guild sign, hoping that you AND word\nof your arrival reach {ql|s} den.",
  "quest.rog.firsttime.synopsis": "[You are in Ransmannsby, where you trained.  Find {ql}.]",
  "quest.rog.goal_first": "You feel a great swelling up of courage, sensing the presence of\n{qo}.  Or is it fear?",
  "quest.rog.goal_first.synopsis": "[You sense {qo}.]",
  "quest.rog.goal_next": "The hairs on the back of your neck whisper -- it's fear.",
  "quest.rog.gotit": "As you pick up {qo}, the hairs on the back of your\nneck fall out.  At once you realize why {qn} was\nwilling to die to keep it out of {ql|s} hands.  Somehow\nyou know that you must do likewise.",
  "quest.rog.gotit.synopsis": "[You pick up {qo} and know that {ql} should not have it.]",
  "quest.rog.guardtalk_after.1": "\"I was sure wrong about Lady Tyvefelle's house; I barely got away with my life and lost my lock pick in the process.\"",
  "quest.rog.guardtalk_after.2": "\"You're back?  Even the Twain don't come back anymore.\"",
  "quest.rog.guardtalk_after.3": "\"Can you spare an old cutpurse a zorkmid for some grog?\"",
  "quest.rog.guardtalk_after.4": "\"Fritz tried to join the other side, and now he's hell-hound chow.\"",
  "quest.rog.guardtalk_after.5": "\"Be careful what you steal, I hear the boss has perfected turning rocks into worthless pieces of glass.\"",
  "quest.rog.guardtalk_before.1": "\"I hear that Lady Tyvefelle's household is lightly guarded.\"",
  "quest.rog.guardtalk_before.2": "\"You're back?  Even the Twain don't come back anymore.\"",
  "quest.rog.guardtalk_before.3": "\"Can you spare an old cutpurse a zorkmid for some grog?\"",
  "quest.rog.guardtalk_before.4": "\"Fritz tried to join the other side, and now he's hell-hound chow.\"",
  "quest.rog.guardtalk_before.5": "\"Be careful what you steal, I hear the boss has perfected turning rocks into worthless pieces of glass.\"",
  "quest.rog.hasamulet": "\"I see that with your abilities, and my brains, we could rule this world.\n\n\"All that we would need to be all-powerful is for you to take that little\ntrinket you've got there up to the Astral Plane.  From there, {qd} will\nshow you what to do with it.  Once that's done, we will be invincible!\"",
  "quest.rog.hasamulet.synopsis": "[Take the Amulet to the Astral Plane and find {qd|s} temple.]",
  "quest.rog.killed_nemesis": "\"I know what you are thinking, {qp}.  It is not too late for you\nto use {qo} wisely.  For the sake of your guild\n{qs|plural}, do what is right.\"\n\nYou sit and wait for death to come for {qn}, and then you\nbrace yourself for your next meeting with {ql}!",
  "quest.rog.killed_nemesis.synopsis": "[Before dying, {qn} tells you to use the {qo} wisely.]",
  "quest.rog.leader_first": "\"Well, look who it is boys -- {qp} has come home.  You seem to have\nfallen behind in your dues.  I should kill you as an example to these\nother worthless cutpurses, but I have a better plan.  If you are ready\nmaybe you could work off your back dues by performing a little job for\nme.  Let us just see if you are ready...\"",
  "quest.rog.leader_first.synopsis": "[You owe back dues to your guild.  You can pay them off if you're up to the job.]",
  "quest.rog.leader_last": "\"Well {qg|plural}, it looks like our friend has forgotten who is the boss\naround here.  Our friend seems to think that {qr|plural} have been put in\ncharge.  Wrong.  DEAD WRONG!\"\n\nYour sudden shift in surroundings prevents you from hearing the end\nof {ql|s} curse.",
  "quest.rog.leader_last.synopsis": "[You must go.]",
  "quest.rog.leader_next": "\"Well, I didn't expect to see you back.  It shows that you are either stupid,\nor you are finally ready to accept my offer.  Let us hope for your sake it\nisn't stupidity that brings you back.\"",
  "quest.rog.leader_next.synopsis": "[Are you stupid or are you ready?]",
  "quest.rog.leader_other": "\"Did you perhaps mistake me for some other {ql|t}?  You must\nthink me as stupid as your behavior.  I warn you not to try my patience.\"",
  "quest.rog.leader_other.synopsis": "[\"Did you perhaps mistake me for some other {ql|t}?  You must think me as stupid as your behavior.  I warn you not to try my patience.\"]",
  "quest.rog.locate_first": "Those damn little hairs tell you that you are nearer to {qo}.",
  "quest.rog.locate_next": "Not wanting to face {ql} without having stolen {qo}, you continue.",
  "quest.rog.nemesis_first": "\"Ah!  You must be {ql|s} ... er, `hero'.  A pleasure to meet you.\"",
  "quest.rog.nemesis_next": "\"We meet again.  Please reconsider your actions.\"",
  "quest.rog.nemesis_other": "\"Surely, {qp}, you have learned that you cannot trust any bargains\nthat {ql} has made.  I can show you how to continue on\nyour quest without having to run into him again.\"",
  "quest.rog.nemesis_other.synopsis": "[You cannot trust {ql}.]",
  "quest.rog.nemesis_wantsit": "\"Please, think for a moment about what you are doing.  Do you truly\nbelieve that {qd} would want {ql} to have\n{qo}?\"",
  "quest.rog.nemesis_wantsit.synopsis": "[{ql|C} should not have {qo}.]",
  "quest.rog.nexttime": "Once again, you find yourself back in Ransmannsby.  Fond memories are\nreplaced by fear, knowing that {ql} is waiting for you.",
  "quest.rog.nexttime.synopsis": "[Once again, you find yourself back in Ransmannsby.  Fond memories are replaced by fear, knowing that {ql} is waiting for you.]",
  "quest.rog.offeredit": "\"Well, I'll be damned.  You got it.  I am proud of you, a fine {qr}\nyou've turned out to be.\n\n\"While you were gone I got to thinking, you and {qo}\ntogether could bring me more treasure than either of you apart, so why don't\nyou take it with you.  All I ask is a cut of whatever loot you come by.\nThat is a better deal than I offered {qn}.\n\n\"But, you see what happened to {qn} when he refused.\nDon't make me find another to send after you this time.\"",
  "quest.rog.offeredit.synopsis": "[Take {qo} with you and go.]",
  "quest.rog.offeredit2": "{ql|C} seems tempted to swap {qo} for\nthe mundane one you detect in his pocket, but noticing your alertness,\nevidently chickens out.\n\n\"Go filch the Amulet before someone else beats you to it.\nThe Dungeons of Doom are back the way you came, through the magic portal.\"",
  "quest.rog.offeredit2.synopsis": "[Take {qo} and acquire the Amulet.]",
  "quest.rog.othertime": "You rub your hands through your hair, hoping that the little ones on\nthe back of your neck stay down, and prepare yourself for your meeting\nwith {ql}.",
  "quest.rog.othertime.synopsis": "[You rub your hands through your hair, hoping that the little ones on the back of your neck stay down, and prepare yourself for your meeting with {ql}.]",
  "quest.rog.posthanks": "\"Quite the little thief, aren't we, {qp}.  Can I interest you in a\nswap for {qo}?  Look around, anything in the keep\nis yours for the asking.\"",
  "quest.rog.posthanks.synopsis": "[How about trading {qo} for something?]",
  "quest.sam.assignquest": "\"Domo {qp}-san, indeed you are ready.  I can now tell you what\nit is that I require of you.\n\n\"The daimyo, {qn}, has betrayed us.  He has stolen from us\n{qo} and taken it to his donjon deep within\n{qi}.\n\n\"If I cannot show the emperor {qo} when he comes\nfor the festival he will know that I have failed in my duty, and\nrequest that I commit seppuku.\n\n\"You must gain entrance to {qi} and retrieve the\nemperor's property.  Be quick!  The emperor will be here for the\ncha-no-you in 5 sticks.\n\n\"Wakarimasu ka?\"",
  "quest.sam.assignquest.synopsis": "[You must enter {qi}, then regain {qo} from {qn}.]",
  "quest.sam.badalign": "\"{qp}-san, you would do better to join the kyokaku.\n\n\"You have skills, but until you can call upon the bushido to know when and\nhow to use them you are not samurai.  When you can think {qa} and\nact {qa} then return.\"",
  "quest.sam.badalign.synopsis": "[When you can think {qa} and act {qa} then return.]",
  "quest.sam.badlevel": "\"{qp}-san, you have learned well and honored your family.\nI require the skills of {qR|an} in order to defeat {qn}.\nGo and seek out teachers.  Learn what they have learned.  When you\nare ready, return to me.\"",
  "quest.sam.badlevel.synopsis": "[\"I require {qR|an} to defeat {qn}.  Return when you are ready.\"]",
  "quest.sam.discourage.1": "\"Ahh, I finally meet the daimyo of the kyokaku!\"",
  "quest.sam.discourage.2": "\"There is no honor for me in your death.\"",
  "quest.sam.discourage.3": "\"You know that I cannot resash my swords until they have killed.\"",
  "quest.sam.discourage.4": "\"Your presence only compounds the dishonor of {ql} in not coming {ql_him}self.\"",
  "quest.sam.discourage.5": "\"I will make tea with your hair and serve it to {ql}.\"",
  "quest.sam.discourage.6": "\"Your fear shows in your eyes, coward!\"",
  "quest.sam.discourage.7": "\"I have not heard of you, {qp}-san; has your life been that unworthy?\"",
  "quest.sam.discourage.8": "\"If you will not obey me, you will die.\"",
  "quest.sam.discourage.9": "\"Kneel now and make the two cuts of honor.  I will tell your {qs|plural} of your honorable death.\"",
  "quest.sam.discourage.10": "\"Your master was a poor teacher.  You will pay for his mistakes in your teaching.\"",
  "quest.sam.encourage.1": "\"To defeat {qn} you must overcome the seven emotions: hate, adoration, joy, anxiety, anger, grief, and fear.\"",
  "quest.sam.encourage.2": "\"Remember your honor is my honor, you perform in my name.\"",
  "quest.sam.encourage.3": "\"I will go to the temple and burn incense for your safe return.\"",
  "quest.sam.encourage.4": "\"Sayonara.\"",
  "quest.sam.encourage.5": "\"There can be honor in defeat, but no gain.\"",
  "quest.sam.encourage.6": "\"Your kami must be strong in order to succeed.\"",
  "quest.sam.encourage.7": "\"You are indeed a worthy {qR}, but now you must be a worthy samurai.\"",
  "quest.sam.encourage.8": "\"If you fail, {qn} will be like a tai-fun on the land.\"",
  "quest.sam.encourage.9": "\"If you are truly {qa}, {qd} will listen.\"",
  "quest.sam.encourage.10": "\"Sharpen your swords and your wits for the task before you.\"",
  "quest.sam.firsttime": "Even before your senses adjust, you recognize the kami of\n{qH}.\n\nYou {qx} the standard of your teki, {qn}, flying above\nthe town.  How could such a thing have happened?  Why are ninja\nwandering freely; where are the samurai of your daimyo, {ql}?\n\nYou quickly say a prayer to Izanagi and Izanami and walk towards\ntown.",
  "quest.sam.firsttime.synopsis": "[The banner of {qn} flies above town.  What has happened to {ql}?]",
  "quest.sam.goal_alt": "As you arrive once again at the home of {qn}.",
  "quest.sam.goal_first": "In your mind, you hear the taunts of {qn}.\n\nYou become like the rice plant and bend to the ground, offering a\nprayer to {qd}.  But when the wind has passed, you stand\nproudly again.  Putting your kami in the hands of fate, you advance.",
  "quest.sam.goal_first.synopsis": "[You feel the taunts {qn}, but after offering a prayer to {qd}, you proceed.]",
  "quest.sam.goal_next": "As you arrive once again at the home of {qn}, your thoughts\nturn only to {qo}.",
  "quest.sam.goal_next.synopsis": "[As you arrive once again at the home of {qn}, your thoughts turn only to {qo}.]",
  "quest.sam.gotit": "As you pick up {qo}, you feel the strength of its karma.\nYou realize at once why so many good samurai had to die to defend it.\nYou are humbled knowing that you hold one of the artifacts of the\nsun goddess.",
  "quest.sam.gotit.synopsis": "[You feel the power of {qo} and are humbled.]",
  "quest.sam.guardtalk_after.1": "\"Come, join us in celebrating with some sake.\"",
  "quest.sam.guardtalk_after.2": "\"Ikaga desu ka?\"",
  "quest.sam.guardtalk_after.3": "\"You have brought our clan and {ql} much honor.\"",
  "quest.sam.guardtalk_after.4": "\"Please {qr}, sit for a while and tell us how you overcame the Ninja.\"",
  "quest.sam.guardtalk_after.5": "\"{ql|C} still lives!  You have saved us from becoming ronin.\"",
  "quest.sam.guardtalk_before.1": "\"To succeed, you must walk like a butterfly on the wind.\"",
  "quest.sam.guardtalk_before.2": "\"Ikaga desu ka?\"",
  "quest.sam.guardtalk_before.3": "\"I fear for The Land of The Gods.\"",
  "quest.sam.guardtalk_before.4": "\"{qn|C} has hired the Ninja -- be careful.\"",
  "quest.sam.guardtalk_before.5": "\"If {qo} is not returned, we will all be ronin.\"",
  "quest.sam.hasamulet": "\"Ah, {qp}-sama.  You have wasted your efforts returning home.\nNow that you are in possession of the Amulet, you are honor-bound to\nfinish the quest you have undertaken.  There will be plenty of time\nfor saki and stories when you have finished.\n\n\"Go now, and may our prayers be a wind at your back.\"",
  "quest.sam.hasamulet.synopsis": "[Take the Amulet to the Astral Plane to finish your task.]",
  "quest.sam.killed_nemesis": "Your healing skills tell you that {qn|s} wounds are mortal.\n\nYou know that the bushido tells you to finish him and let his kami\ndie with honor, but the thought of so many samurai dead due to this\nman's dishonor prevents you from giving the final blow.\n\nYou order that his unwashed head be given to the crows and his body\nthrown into the sea.",
  "quest.sam.killed_nemesis.synopsis": "[{qn|C} dies without honor.]",
  "quest.sam.leader_first": "\"Ah, {qp}-san, it is good to see you again.  I need someone who can\nlead my samurai against {qn}.  If you are ready, you will be\nthat person.\"",
  "quest.sam.leader_first.synopsis": "[{ql|C} needs someone to lead {ql_his} samurai against {qn}.  Are you ready?]",
  "quest.sam.leader_last": "\"You are no longer my samurai, {qp}.\n\n\"Hara-kiri is denied.  You are ordered to shave your head and then to\nbecome a monk.  Your fief and family are forfeit.  Wakarimasu ka?\"",
  "quest.sam.leader_last.synopsis": "[Leave and do not come back.]",
  "quest.sam.leader_next": "\"Once again, {qp}-san, you kneel before me.  Are you yet capable of\nbeing my vassal?\"",
  "quest.sam.leader_next.synopsis": "[\"Once again, {qp}-san, you kneel before me.  Are you yet capable of being my vassal?\"]",
  "quest.sam.leader_other": "\"You begin to test my matsu, {qp}-san.\nIf you cannot determine what I want in a samurai, how can I rely on you\nto figure out what I need from a samurai?\"",
  "quest.sam.leader_other.synopsis": "[Are you truly a samurai?]",
  "quest.sam.locate_first": "You instinctively reach for your swords.  You do not recognize the\nlay of this land, but you know that your teki are everywhere.",
  "quest.sam.locate_first.synopsis": "[You instinctively reach for your swords.  You do not recognize the lay of this land, but you know that your teki are everywhere.]",
  "quest.sam.locate_next": "Thankful that your {qs|plural} at {qH} cannot see\nyour fear, you prepare again to advance.",
  "quest.sam.locate_next.synopsis": "[Thankful that your {qs|plural} at {qH} cannot see your fear, you prepare again to advance.]",
  "quest.sam.nemesis_first": "\"Ah, so it is to be you, {qp}-san.  I offer you seppuku.\nI will be your second if you wish.\"",
  "quest.sam.nemesis_first.synopsis": "[\"Ah, so it is to be you, {qp}-san.  I offer you seppuku. I will be your second if you wish.\"]",
  "quest.sam.nemesis_next": "\"I have offered you the honorable exit.  Now I will have your\nhead to send unwashed to {ql}.\"",
  "quest.sam.nemesis_next.synopsis": "[\"I have offered you the honorable exit.  Now I will have your head to send unwashed to {ql}.\"]",
  "quest.sam.nemesis_other": "\"After I have dispatched you, I will curse your kami.\"",
  "quest.sam.nemesis_wantsit": "\"You have fought my samurai; surely you must know that you\nwill not be able to take {qo} back to\n{qH}.\"",
  "quest.sam.nemesis_wantsit.synopsis": "[\"You have fought my samurai; surely you must know that you will not be able to take {qo} back to {qH}.\"]",
  "quest.sam.nexttime": "Once again, you are back at {qH}.",
  "quest.sam.offeredit": "As you bow before {ql}, he welcomes you:\n\n    \"You have brought your family great honor, {qp}-sama.\n\n    \"While you have been gone the emperor's advisors have discovered in\n    the ancient texts that the karma of the samurai who seeks to recover\n    the Amulet and the karma of {qo} are joined\n    as the seasons join to make a year.\n\n    \"Because you have shown such fidelity, the emperor requests\n    that you take leave of other obligations and continue on the\n    road that fate has set your feet upon.  I would consider it\n    an honor if you would allow me to watch your household until\n    you return with the Amulet.\"\n\nWith that, {ql} bows, and places his sword atop\n{qo}.",
  "quest.sam.offeredit.synopsis": "[The emperor wants you to take {qo} and recover the Amulet.]",
  "quest.sam.offeredit2": "{ql} holds {qo} tightly for a moment, then returns\nhis gaze to you.\n\n\"The time is ripe to recover the Amulet.  Return to The Dungeons of Doom\nthrough the magic portal that transported you here so that you may\nachieve the destiny which awaits you.\"",
  "quest.sam.offeredit2.synopsis": "[Take {qo}, return to The Dungeons of Doom, and recover the Amulet.]",
  "quest.sam.othertime": "You are back at {qH}.\n\nInstantly you sense a subtle change in your karma.  You seem to know that\nif you do not succeed in your quest, {qn} will have destroyed\nthe kami of {qH} before you return again.",
  "quest.sam.othertime.synopsis": "[{qH|C} is threatened by {qn}.]",
  "quest.sam.posthanks": "{ql|C} bows.  \"{qp}-sama, tell us of your search for the Amulet.\"",
  "quest.tou.assignquest": "\"Yes, you've become a great {qc} since I last saw you.\n\t\t \n\"Sadly, things haven't been going so well here in {qH}.  A new\n{qn|t} was appointed, and he hosted a dinner to meet other civic\nleaders.  At the door, one of his henchmen offered to look after my wallet.\n\n\"I know what you're thinking:  'How kind!'  But it turns out that even in the\nThieves' Guild, there are people you can't trust.  My wallet contained -- you\nknow the Royal Mint has been trialing credit cards, so we won't have to carry\nbags of gold around?  Most of the prototypes haven't worked, and are only\ngood for picking locks.  This one, {qo}, is\none of a kind.  As the highest spending and most often mugged resident of\n{qH}, it was entrusted to me.  But when I got my wallet back, the Card was\nmissing.  I appealed to the Patrician, and he said the matter fell under the\ndoctrine of _detectores custodes_.\n\n\"We believe {qn} has the Card, and that he's holed himself\nup in {qi}.  With the power of {qo}, the\nThieves are bolder than ever.  Citizens are frightened, and tourism is\ndown. We need somebody to find their way into {qi} and\nrecover the Card before there are no {qc|plural} left!\n\n\"So, {qp}, are you ready for a little Detour?\"",
  "quest.tou.assignquest.synopsis": "[Enter {qi} and recover {qo} from {qn}.]",
  "quest.tou.badalign": "\"Oh, {qp}, you haven't stayed true to the {qa} path.  You know\n{qd} doesn't like it when you stray.  You can't possibly go after\n{qn} like this!\n\n\"Get back to the Dungeon.  Work on yourself.  Come back when you're truly\n{qa}, and we'll talk.\"",
  "quest.tou.badalign.synopsis": "[You are not sufficiently {qa}.  Return when you are.]",
  "quest.tou.badlevel": "\"{qp|C}, you're still only {qr|an}.  I don't think you're\nprepared to take on {qn} yet.\n\n\"Carry on with your Tour.  Explore.  Take photos.  Learn things.  Come back\nwhen you're a {qR}, and you might stand a chance.\n{qn|C} will still be here when you're ready for him.\"",
  "quest.tou.badlevel.synopsis": "[Return when you are {qR|an}.]",
  "quest.tou.discourage.1": "\"I beat {ql} real bad and I'll beat you even worse, {qp}.\"",
  "quest.tou.discourage.2": "\"Not even {qd} can help you here.\"",
  "quest.tou.discourage.3": "\"Beg for mercy, and maybe I'll consider thinking about going easy on you.\"",
  "quest.tou.discourage.4": "\"You coulda made a good Thief if you weren't so damn {qa}.\"",
  "quest.tou.discourage.5": "\"Write your postcards, {qp}.  Your Tour ends here.\"",
  "quest.tou.discourage.6": "\"Couldn't {ql} send me a better {qc} to beat up?\"",
  "quest.tou.discourage.7": "\"With {qo}, I'm gonna run up a bill that'll bankrupt {qH}.\"",
  "quest.tou.discourage.8": "\"Nobody defeats {qn}.  NOBODY!\"",
  "quest.tou.discourage.9": "\"Poor, naive {ql}.  Did he send you to ask me nicely to give {qo} back?\"",
  "quest.tou.discourage.10": "\"How do you spell {qp}?  I want to make sure your grave is spelled right.\"",
  "quest.tou.encourage.1": "\"Who'd have thought {qn} would be such a criminal!\"",
  "quest.tou.encourage.2": "\"Look out for the traps on the way to {qi}.  Some date back to the Mage Wars!\"",
  "quest.tou.encourage.3": "\"Get {qo} back, and hopefully I can cancel {qn|s} transactions.\"",
  "quest.tou.encourage.4": "\"If you're stuck, try praying to {qd}. {qd_he|C}'s whimsical, but {qd_he} sometimes helps {qc|plural} out.\"",
  "quest.tou.encourage.5": "\"You have to defeat {qn}, or {qn_he}'ll follow you back here!\"",
  "quest.tou.encourage.6": "\"If you can grab {qo} from {qn}, it might help you beat {qn_him}.\"",
  "quest.tou.encourage.7": "\"Hurry, {qp}!  We're all depending on you.\"",
  "quest.tou.encourage.8": "\"I know you won't let me down, {qp}!\"",
  "quest.tou.encourage.9": "\"Stay {qa}.  Remember, {qc|plural} don't take sides, we take photos.\"",
  "quest.tou.encourage.10": "\"If anybody gives you trouble, remember: a smile can go a long way.\"",
  "quest.tou.firsttime": "You come round to find yourself looking at the familiar sights of\n{qH}.  You breathe a sigh of relief, taking in the polluted air.\n\nBut this isn't {qH} as you remember it.  The streets are... quiet?\nDoors close, curtains twitch, and a few residents scurry about nervously, but\nyou can't hear the hawkers selling their ropy meat pies, or the cargo barges\nbulldozing their way along the river.  A whiff of rotten cabbages suggests\nthat the fields outside the city aren't being tended properly.\n\nSomething isn't right.  Hopefully, it's all some sort of misunderstanding.\n{ql|C} will sort it out, when you find him.",
  "quest.tou.firsttime.synopsis": "[You're back at {qH}, but it's still ominously quiet.]",
  "quest.tou.goal_alt": "You're back at {qn|s} lair.",
  "quest.tou.goal_first": "You feel the presence of {qo} nearby.",
  "quest.tou.goal_next": "You'll find {qo} this time, for sure!",
  "quest.tou.gotit": "You feel a rich contentment as you pick up {qo}.\nThat'll do nicely!  You'd better return it to {ql} as soon as possible.",
  "quest.tou.gotit.synopsis": "[You feel contented as you pick up {qo}.  Now to return it to {ql}.]",
  "quest.tou.guardtalk_after.1": "\"Gehennom on 5 zorkmids a day -- more like 500 a day if you ask me.\"",
  "quest.tou.guardtalk_after.2": "\"Do you know where I could find some nice postcards of The Gnomish Mines?\"",
  "quest.tou.guardtalk_after.3": "\"Have you tried the weird toilets?\"",
  "quest.tou.guardtalk_after.4": "\"If you stick around, I'll show you the pictures from my latest trip.\"",
  "quest.tou.guardtalk_after.5": "\"Did you bring me back any souvenirs?\"",
  "quest.tou.guardtalk_before.1": "\"Gehennom on 5 zorkmids a day -- more like 500 a day if you ask me.\"",
  "quest.tou.guardtalk_before.2": "\"Do you know where I could find some nice postcards of The Gnomish Mines?\"",
  "quest.tou.guardtalk_before.3": "\"Have you tried the weird toilets?\"",
  "quest.tou.guardtalk_before.4": "\"Don't stay at the Inn, I hear the food is terrible and it has rats.\"",
  "quest.tou.guardtalk_before.5": "\"They told me that this was the off season!\"",
  "quest.tou.hasamulet": "\"{qp|C}!  And you found the Amulet of Yendor?  Amazing!\n\n\"But you can't keep it here in {qH}.  It won't be safe!\n\n\"Besides, the Amulet isn't for us {qc|plural}, it's for {qd}.  I've heard\n{qd_he} has a temple on the Astral Plane, which incidentally is a gorgeous place\nto visit this time of year.  Find your way there, then offer it to {qd}\non {qd_his} high altar.  {qd_he|C}'ll be delighted to have it to {qd_him|C}self at last!\n\nSafe journey, {qp}.\"",
  "quest.tou.hasamulet.synopsis": "[You have the Amulet.  Take it to the Astral Plane to finish your task.]",
  "quest.tou.killed_nemesis": "{qn|C}' body buckles.  As he gasps for breath, {qn_he} manages to\ncurse:\n\n\"You won't get away, {qp}!  My guys will come after you wherever\nyou go, and take {qo} back for the Thieves.\"\nAnd he's gone.\n\nFor a moment, a black cloaked figure flickers in the corner of your eye, and\nyou thought you could hear hoofbeats.",
  "quest.tou.killed_nemesis.synopsis": "[{qn|C} curses at you as {qn_he} dies.]",
  "quest.tou.leader_first": "\"Aloha {qp}, it's so good to see you!  How goes your Tour?\n\nListen, I'm so sorry to cut your vacation short, but we've got a little bit\nof a situation here.  Somebody has to do something about\n{qn}!  Could that somebody be you?  Let me take a look at you...\"",
  "quest.tou.leader_first.synopsis": "[Someone must defeat {qn}.  Are you ready?]",
  "quest.tou.leader_last": "\"Oh, no, {qp}.  You're no {qc}.  Leave {qH}, and don't show your\nface here again.  Your membership of the {qH} Guild of Trespassers\nis revoked.  Aloha.\"",
  "quest.tou.leader_last.synopsis": "[Leave {qH} and never return.]",
  "quest.tou.leader_next": "\"Aloha again, {qp}.  Feeling ready this time?\"",
  "quest.tou.leader_other": "\"I hope you've prepared yourself this time.\"",
  "quest.tou.locate_first": "This isn't the friendliest part of town.  There are Thieves' marks\neverywhere, and {qn|s} flunkies creep along the alleyways.",
  "quest.tou.locate_first.synopsis": "[You {qx} the handiwork of {qn|s} flunkies.]",
  "quest.tou.locate_next": "You know that this time you'll have to destroy {qn}.",
  "quest.tou.nemesis_first": "\"So, {qp}, {ql} thinks you're gonna take\n{qo} from me.  How cute is that?\n\n\"He sends {qr|an} to defeat me.  Me!  When this is over, I'll put you\nin cement shoes and throw you onto the river!\"",
  "quest.tou.nemesis_first.synopsis": "[{qr|An} will not defeat me.]",
  "quest.tou.nemesis_next": "\"I let you get away the last time, {qp}.  This\ntime, I'll destroy you.\"",
  "quest.tou.nemesis_next.synopsis": "[\"I let you get away the last time, {qp}.  This time, I'll destroy you.\"]",
  "quest.tou.nemesis_other": "\"These meetings are starting to bore me.  You're eating into my precious\nscheming time.\n\n\"If you don't run away now, I'm gonna make you suffer so bad that {ql}\nwill feel guilty for sending you here.\"",
  "quest.tou.nemesis_other.synopsis": "[Run away or you will suffer severely.]",
  "quest.tou.nemesis_wantsit": "\"You putz.  You don't even know how to use\n{qo}.  Give it back to me and I'll teach you,\nand together, we can rule {qH}.  And we really can!  I'm not just\nsaying that so you'll give me {qo} back, I\nswear.  Thief's honor!\n\n\"But do it now, 'cause I'm running out of patience.\"",
  "quest.tou.nemesis_wantsit.synopsis": "[\"Return {qo} to me and we will rule {qH}.\"]",
  "quest.tou.nexttime": "Once again, you are back at {qH}.",
  "quest.tou.offeredit": "{ql|C} takes {qo} and\nflexes it in his hand, then looks up and smiles.\n\n\"{qp|C}, while you were away, {qd} appeared to me, and suggested I\ntransfer {qo} to you.  Carry it with you on\nyour quest for the Amulet of Yendor, and you'll travel in good company.\n\n\"Remember -- there are some things gold can buy.  For everything else,\nthere's {qo}.\"",
  "quest.tou.offeredit.synopsis": "[Take {qo} and with {qd|s} guidance, recover the Amulet.]",
  "quest.tou.offeredit2": "\"{qo|C} is yours.  Don't leave home without it!\nThe Dungeons of Doom are right on the other side of the magic portal you used\nto get here.\"",
  "quest.tou.offeredit2.synopsis": "[Keep {qo} and return to The Dungeons of Doom through the portal.]",
  "quest.tou.othertime": "You are back at {qH}.  Things are looking so dead,\nyou feel there may soon be no {qc|s} here at all.",
  "quest.tou.othertime.synopsis": "[You are back at {qH}.  Things are looking so dead, you feel there may soon be no {qc|s} here at all.]",
  "quest.tou.posthanks": "\"Just look at you, {qp}!  Tell me all about your Tour.  Did you\nfind the Amulet of Yendor yet?\"",
  "quest.tou.posthanks.synopsis": "[\"Just look at you, {qp}!  Tell me all about your Tour.  Did you find the Amulet of Yendor yet?\"]",
  "quest.val.assignquest": "\"It is not clear, {qp}, for my sight is limited without our relic.\nBut it is now likely that you can defeat {qn}, and recover\n{qo}.\n\n\"A short time ago, {qn} and his minions attacked this place.  They\nopened the huge volcanic vents you {qx} about the hill, and attacked.  I knew\nthat this was to come to pass, and had asked {qd} for a group of {qg|Plural}\nto help defend this place.  The few you {qx} here are the mightiest of\nValhalla's own, and are all that are left of one hundred {qd} sent.\n\n\"Despite the great and glorious battle we fought, {qn} managed at\nlast to steal {qo}.  This has upset the balance of the universe,\nand unless {qo_he} is returned into my care, {qn} may start Ragnarok.\n\n\"You must find the entrance to {qi}.  Travel downward\nfrom there and you will find {qn|s} lair.  Defeat him and\nreturn {qo} to me.\"",
  "quest.val.assignquest.synopsis": "[Find {qi}; defeat {qn}; return with {qo}.]",
  "quest.val.badalign": "\"NO!  This is terrible.  I see you becoming an ally of {qn}, and\nleading his armies in the final great battles.  This must not come to\npass!  You have strayed from the {qa} path.  You must purge yourself,\nand return here only when you have regained a state of purity.\"",
  "quest.val.badalign.synopsis": "[You have strayed from the {qa} path.  Return after you purify yourself.]",
  "quest.val.badlevel": "\"I see you and {qn} fighting, {qp}.  But you are not prepared and\nshall die at {qn|s} hand if you proceed.  No.  This will not do.\nGo back out into the world, and grow more experienced at the ways of war.\nOnly when you have returned {qR|an} will you be able to defeat {qn}.\"",
  "quest.val.badlevel.synopsis": "[Come back when you are {qR|an}.]",
  "quest.val.discourage.1": "\"I am your death, {qc}.\"",
  "quest.val.discourage.2": "\"You cannot prevail, {qr}.  I have foreseen your every move.\"",
  "quest.val.discourage.3": "\"With you out of the way, Valhalla will be mine for the taking.\"",
  "quest.val.discourage.4": "\"I killed scores of {qd|s} best when I took {qo}. Do you really think that one {qc} can stand against me?\"",
  "quest.val.discourage.5": "\"Who bears the souls of {qc|Plural} to Valhalla, {qr}?\"",
  "quest.val.discourage.6": "\"No, {qd} cannot help you here.\"",
  "quest.val.discourage.7": "\"Some instrument of {qd} you are, {qp}.  You are a weakling!\"",
  "quest.val.discourage.8": "\"Never have I seen {qc|an} so clumsy in battle.\"",
  "quest.val.discourage.9": "\"You die now, little {qs}.\"",
  "quest.val.discourage.10": "\"Your body I destroy now, your soul when my hordes overrun Valhalla!\"",
  "quest.val.encourage.1": "\"Go with the blessings of {qd}.\"",
  "quest.val.encourage.2": "\"Call upon {qd} when you are in need.\"",
  "quest.val.encourage.3": "\"Use {qo} if you can.  It will protect you.\"",
  "quest.val.encourage.4": "\"Magical cold is very effective against {qn}.\"",
  "quest.val.encourage.5": "\"To face {qn}, you will need to be immune to fire.\"",
  "quest.val.encourage.6": "\"May {qd} strengthen your sword-arm.\"",
  "quest.val.encourage.7": "\"Trust in {qd}.  He will not desert you.\"",
  "quest.val.encourage.8": "\"It becomes more likely that Ragnarok will come with every passing moment. You must hurry, {qp}.\"",
  "quest.val.encourage.9": "\"If {qn} can master {qo}, he will be powerful enough to face {qd} far earlier than is fated.  This must not be!\"",
  "quest.val.encourage.10": "\"Remember your training, {qp}.  You can succeed.\"",
  "quest.val.firsttime": "You materialize at the base of a snowy hill.  Atop the hill sits\na place you know well, {qH}.  You immediately realize\nthat something here is very wrong!\n\nIn places, the snow and ice have been melted into steaming pools of\nwater.  Fumaroles and pools of bubbling lava surround the hill.\nThe stench of sulphur is carried through the air, and you {qx} creatures\nthat should not be able to live in this environment moving towards you.",
  "quest.val.firsttime.synopsis": "[You arrive below {qH}.  Something is wrong; there is lava present.]",
  "quest.val.goal_first": "Through clouds of sulphurous gasses, you {qx} a rock palisade\nsurrounded with a moat of bubbling lava.  You remember the description\nfrom something that {ql} said.  This is the lair of {qn}.",
  "quest.val.goal_first.synopsis": "[This is the lair of {qn}.]",
  "quest.val.goal_next": "Once again, you stand in sight of {qn|s} lair.",
  "quest.val.gotit": "As you pick up {qo}, your mind is suddenly filled with images,\nand you perceive all of the possibilities of each potential choice you\ncould make.  As you begin to control and channel your thoughts, you\nrealize that you must return {qo} to {ql} immediately.",
  "quest.val.gotit.synopsis": "[You must return {qo} to {ql}.]",
  "quest.val.guardtalk_after.1": "\"Hail, and well met, brave {qc}.\"",
  "quest.val.guardtalk_after.2": "\"May {qd} guide your steps, {qp}.\"",
  "quest.val.guardtalk_after.3": "\"{ql|C} told us you had succeeded!\"",
  "quest.val.guardtalk_after.4": "\"You recovered {qo} just in time, {qp}.\"",
  "quest.val.guardtalk_after.5": "\"Hail {qd}, for delivering {qo} back to us.\"",
  "quest.val.guardtalk_before.1": "\"Hail, and well met, brave {qc}.\"",
  "quest.val.guardtalk_before.2": "\"May {qd} guide your steps, {qp}.\"",
  "quest.val.guardtalk_before.3": "\"{ql|C} weakens.  Without {qo}, her foresight is dim.\"",
  "quest.val.guardtalk_before.4": "\"You must hurry, {qp}, else Ragnarok may well come.\"",
  "quest.val.guardtalk_before.5": "\"I would deal with this foul {qn} myself, but {qd} forbids it.\"",
  "quest.val.hasamulet": "\"Excellent, {qp}.  I see you have recovered the Amulet!\n\n\"You must take the Amulet to the Great Temple of {qd}, on the Astral\nPlane.  There you must offer the Amulet to {qd}.\n\n\"Go now, my {qS}.  I cannot tell you your fate, as the power of the\nAmulet interferes with mine.  I hope for your success.\"",
  "quest.val.hasamulet.synopsis": "[Take the Amulet to {qd|s} temple on the Astral Plane and offer it.]",
  "quest.val.killed_nemesis": "A look of surprise and horror appears on {qn|s} face.\n\n    \"No!!!  {qo} has lied to me!  I have been misled!\"\n\nSuddenly, {qn} grasps his head and screams in agony, then dies.",
  "quest.val.killed_nemesis.synopsis": "[{qn|C} dies.]",
  "quest.val.leader_first": "\"Ah, {qp}, my {qS}.  You have returned to {qH}\nat last.  We are in dire need of your aid, but I must determine if you\nare yet ready for such an undertaking.\n\n\"Let me read your fate...\"",
  "quest.val.leader_first.synopsis": "[We need your aid.  Are you ready?]",
  "quest.val.leader_last": "\"No, {qp}.  Your fate is sealed.  I must cast about for another\nchampion.  Begone from my presence, and never return.  Know this, that\nyou shall never succeed in this life, and Valhalla is denied to you.\"",
  "quest.val.leader_last.synopsis": "[\"Begone from my presence and never return.\"]",
  "quest.val.leader_next": "\"Let me read the future for you now, {qp}, perhaps you have managed to\nchange it enough...\"",
  "quest.val.leader_next.synopsis": "[\"Let me read the future for you now, {qp}, perhaps you have managed to change it enough...\"]",
  "quest.val.leader_other": "\"Again, I shall read your fate, my {qS}.  Let us both hope that you have\nmade changes to become ready for this task...\"",
  "quest.val.leader_other.synopsis": "[\"Again, I shall read your fate, my {qS}.  Let us both hope that you have made changes to become ready for this task...\"]",
  "quest.val.locate_first": "The ice and snow gives way to a valley floor.  You {qx} ahead of you\na huge round hill surrounded by pools of lava.  This then is the entrance\nto {qi}.  It looks like you're not going to get in without\na fight though.",
  "quest.val.locate_first.synopsis": "[This is the entrance to {qi}.]",
  "quest.val.locate_next": "Once again, you stand before the entrance to {qi}.",
  "quest.val.nemesis_first": "\"So!  {ql|C} has finally sent {qc|an} to challenge me!\n\n\"I thought that mastering {qo} would enable me to challenge\n{qd}, but it has shown me that first I must kill you!  So come, little\n{qs}.  Once I defeat you, I can at last begin the final battle with {qd}.\"",
  "quest.val.nemesis_first.synopsis": "[\"{qo|C} has shown me that I must kill you.\"]",
  "quest.val.nemesis_next": "\"Again you challenge me, {qr}.  Good.  I will kill you now.\"",
  "quest.val.nemesis_other": "\"Have you not learned yet?  You cannot defeat {qn}!\"",
  "quest.val.nemesis_wantsit": "\"I will kill you, {qc}, and wrest {qo} from your mangled hands.\"",
  "quest.val.nexttime": "Once again, you are near the abode of {ql}.",
  "quest.val.offeredit": "As you approach, {ql} rises and touches {qo}.\n\n\"You may take {qo} with you, {qp}.  I have removed from\nit the power to foretell the future, for that power no mortal should\nhave.  Its other abilities, however, you have at your disposal.\n\n\"You must now begin in {qd|s} name to search for the Amulet of Yendor.\nMay your steps be guided by {qd}, my {qS}.\"",
  "quest.val.offeredit.synopsis": "[Take {qo}.  Search for the Amulet.]",
  "quest.val.offeredit2": "\"Careful, {qp}!  {qo|C} might break, and that would be\na tragic loss.  You are its keeper now, and the time has come to\nresume your search for the Amulet.  The Dungeons of Doom await your\nreturn through the magic portal that brought you here.\"",
  "quest.val.offeredit2.synopsis": "[You are {qo|s} keeper now.  Return through the portal and find the Amulet.]",
  "quest.val.othertime": "Again you materialize near {ql|s} abode.  You have a nagging feeling\nthat this may be the last time you come here.",
  "quest.val.othertime.synopsis": "[Again you materialize near {ql|s} abode.  You have a nagging feeling that this may be the last time you come here.]",
  "quest.val.posthanks": "\"Greetings, {qp}.  I have not been able to pay as much attention to\nyour search for the Amulet as I have wished.  How do you fare?\"",
  "quest.val.posthanks.synopsis": "[\"Greetings, {qp}.  I have not been able to pay as much attention to your search for the Amulet as I have wished.  How do you fare?\"]",
  "quest.wiz.assignquest": "\"Yes, {qp}, you truly are ready for this dire task.  Listen,\ncarefully, for what I tell you now will be of vital importance.\n\n\"Since you left us to hone your skills in the world, we unexpectedly came\nunder attack by the forces of {qn}.  As you know, we thought\n{qn} had perished at the end of the last age, but, alas, this was\nnot the case.\n\n\"{qn|C} sent an army of abominations against us.  Among them was a\nminion, mindless and ensorcelled, and thus, in the confusion, it was\nable to penetrate our defenses.  Alas, this creature has stolen\n{qo} and I fear has delivered {qo_he} to {qn}.\n\n\"Over the years, I had woven most of my power into this amulet, and thus,\nwithout it, I have but a shadow of my former power, and I fear that I\nshall soon perish.\n\n\"You must travel to {qi}, and within its dungeons,\nfind and overcome {qn}, and return {qo} to me.\n\n\"Go now, with {qd}, and complete this quest before it is too late.\"",
  "quest.wiz.assignquest.synopsis": "[Travel to {qi}; overcome {qn}; return with {qo}.]",
  "quest.wiz.badalign": "\"You amaze me, {qp}!  How many times did I tell you that the way of a mage\nis an exacting one.  One must use the world with care, lest one leave it\nin ruins and simplify the task of {qn}.\n\n\"You must go back and show your worthiness.  Do not return until you are\ntruly ready for this quest.  May {qd} guide you in this task.\"",
  "quest.wiz.badalign.synopsis": "[Go; come back when you are worthy of {qd}.]",
  "quest.wiz.badlevel": "\"Alas, {qp}, you have not yet shown your proficiency as a worthy\nspellcaster.  As {qr|an}, you would surely be overcome in the challenge\nahead.  Go, now, expand your horizons, and return when you have attained\nrenown as {qR|an}.\"",
  "quest.wiz.badlevel.synopsis": "[Go; return when you are {qR|an}.]",
  "quest.wiz.discourage.1": "\"Your puny powers are no match for me, fool!\"",
  "quest.wiz.discourage.2": "\"When you are defeated, your torment will last for a thousand years.\"",
  "quest.wiz.discourage.3": "\"After your downfall, {qp}, I shall devour {ql} for dessert!\"",
  "quest.wiz.discourage.4": "\"Are you ready yet to beg for mercy?  I could be lenient...\"",
  "quest.wiz.discourage.5": "\"Your soul shall join the enslaved multitude I command!\"",
  "quest.wiz.discourage.6": "\"Your lack of will is evident, and you shall die as a result.\"",
  "quest.wiz.discourage.7": "\"Your faith in {qd} is for naught!  Come, submit to me now!\"",
  "quest.wiz.discourage.8": "\"A mere {qr} is nothing compared to my skill!\"",
  "quest.wiz.discourage.9": "\"So, you are the best hope of {ql}?  How droll.\"",
  "quest.wiz.discourage.10": "\"Feel my power, {qc}!  My victory is imminent!\"",
  "quest.wiz.encourage.1": "\"Beware, for {qn} is immune to most magical attacks.\"",
  "quest.wiz.encourage.2": "\"To enter {qi} you must pass many traps.\"",
  "quest.wiz.encourage.3": "\"{qn|C} may be vulnerable to physical attacks.\"",
  "quest.wiz.encourage.4": "\"{qd} will come to your aid when you call.\"",
  "quest.wiz.encourage.5": "\"You must utterly destroy {qn}.  He will pursue you otherwise.\"",
  "quest.wiz.encourage.6": "\"{qo|C} is a mighty artifact.  With it you can destroy {qn}.\"",
  "quest.wiz.encourage.7": "\"Go forth with the blessings of {qd}.\"",
  "quest.wiz.encourage.8": "\"I will have my {qg|Plural} watch for your return.\"",
  "quest.wiz.encourage.9": "\"Feel free to take any items in that chest that might aid you.\"",
  "quest.wiz.encourage.10": "\"You will know when {qo} is near.  Proceed with care!\"",
  "quest.wiz.firsttime": "You are suddenly in familiar surroundings.  You notice what appears to\nbe a large, squat stone structure nearby.  Wait!  That looks like the\ntower of your former teacher, {ql}.\n\nHowever, things are not the same as when you were last here.  Mists and\nareas of unexplained darkness surround the tower.  There is movement in\nthe shadows.\n\nYour teacher would never allow such unaesthetic forms to surround the\ntower...  unless something were dreadfully wrong!",
  "quest.wiz.firsttime.synopsis": "[You have arrived at {ql|s} tower but something is very wrong.]",
  "quest.wiz.goal_alt": "You have returned to {qn|s} lair.",
  "quest.wiz.goal_first": "You feel your mentor's presence; perhaps {qo} is nearby.",
  "quest.wiz.goal_next": "The aura of {qo} tingles at the edge of your perception.",
  "quest.wiz.gotit": "As you touch {qo}, its comforting power infuses you\nwith new energy.  You feel as if you can detect others' thoughts flowing\nthrough it.  Although you yearn to wear {qo} and\nattack the Wizard of Yendor, you know you must return it to its rightful\nowner, {ql}.",
  "quest.wiz.gotit.synopsis": "[You feel {qo|s} power and know you should return {qo_he} to {ql}.]",
  "quest.wiz.guardtalk_after.1": "\"I have some eye of newt to trade, do you have a spare blind-worm's sting?\"",
  "quest.wiz.guardtalk_after.2": "\"The magic portal now seems like it will remain stable for quite some time.\"",
  "quest.wiz.guardtalk_after.3": "\"Have you noticed how much stronger {ql} is since {qo} was recovered?\"",
  "quest.wiz.guardtalk_after.4": "\"Thank {qd}!  We weren't positive you would defeat {qn}.\"",
  "quest.wiz.guardtalk_after.5": "\"I, too, will venture into the world, because {qn} was but one of many evils to be vanquished.\"",
  "quest.wiz.guardtalk_before.1": "\"Would you happen to have some eye of newt in that overstuffed pack, {qs}?\"",
  "quest.wiz.guardtalk_before.2": "\"Ah, the spell to create the magic portal worked.  Outstanding!\"",
  "quest.wiz.guardtalk_before.3": "\"Hurry!  {ql|C} may not survive that casting of the portal spell!\"",
  "quest.wiz.guardtalk_before.4": "\"The spells of {qn} were just too powerful for us to withstand.\"",
  "quest.wiz.guardtalk_before.5": "\"I, too, will venture into the world, because {qn} is but one of many evils to be vanquished.\"",
  "quest.wiz.hasamulet": "\"Congratulations, {qp}.  I always knew that if anyone could succeed\nin defeating the Wizard of Yendor and his minions, it would be you.\n\n\"Go now, and take the Amulet to the Astral Plane.  Once there, present\nthe Amulet on the altar of {qd}.  Along the way you shall pass through\nthe four Elemental Planes.  These planes are like nothing you have ever\nexperienced before, so be prepared!\n\n\"For this you were born, {qs}!  I am very proud of you.\"",
  "quest.wiz.hasamulet.synopsis": "[Take the Amulet to {qd|s} altar on the Astral Plane.]",
  "quest.wiz.killed_nemesis": "{qn|C}, whose body begins to shrivel up, croaks out:\n\n    \"I shall haunt your progress until the end of time.  A thousand\n    curses on you and {ql}.\"\n\nThen, the body bursts into a cloud of choking dust, and blows away.",
  "quest.wiz.killed_nemesis.synopsis": "[{qn|C} curses you as {qn_he} dies.]",
  "quest.wiz.leader_first": "\"Come closer, {qp}, for my voice falters in my old age.\nYes, I see that you have come a long way since you went out into the\nworld, leaving the safe confines of this tower.  However, I must first\ndetermine if you have all of the skills required to take on the task\nI require of you.\"",
  "quest.wiz.leader_first.synopsis": "[You have come a long way, but are you ready for the task I require?]",
  "quest.wiz.leader_last": "\"You fool, {qp}!  Why did I waste all of those years teaching you\nthe esoteric arts?  Get out of here!  I shall find another.\"",
  "quest.wiz.leader_last.synopsis": "[\"Get out of here!\"]",
  "quest.wiz.leader_next": "\"Well, {qp}, you have returned.  Perhaps you are now ready...\"",
  "quest.wiz.leader_other": "\"This is getting tedious, {qp}, but perseverance is a sign of a true mage.\nI certainly hope that you are truly ready this time!\"",
  "quest.wiz.leader_other.synopsis": "[\"This is getting tedious, {qp}, but perseverance is a sign of a true mage. I certainly hope that you are truly ready this time!\"]",
  "quest.wiz.locate_first": "Wisps of fog swirl nearby.  You feel that {qn|s} lair is close.",
  "quest.wiz.locate_next": "You believe that you may once again invade {qi}.",
  "quest.wiz.nemesis_first": "\"Ah, I recognize you, {qp}.  So, {ql} has sent you to steal\n{qo} from me, hmmm?  Well, {ql_he} is a fool to send such\na mental weakling against me.\n\n\"Your destruction, however, should make for good sport.  In the end, you\nshall beg me to kill you!\"",
  "quest.wiz.nemesis_first.synopsis": "[\"Your destruction should make for good sport.\"]",
  "quest.wiz.nemesis_next": "\"How nice of you to return, {qp}!  I enjoyed our last meeting.  Are you\nstill hungry for more pain?\n\n\"Come!  Your soul, like {qo}, shall soon be mine to command.\"",
  "quest.wiz.nemesis_next.synopsis": "[\"Your soul shall soon be mine to command.\"]",
  "quest.wiz.nemesis_other": "\"I'm sure that your perseverance shall be the subject of innumerable\nballads, but you shall not be around to hear them, I fear!\"",
  "quest.wiz.nemesis_other.synopsis": "[\"I'm sure that your perseverance shall be the subject of innumerable ballads, but you shall not be around to hear them, I fear!\"]",
  "quest.wiz.nemesis_wantsit": "\"Thief!  {qo|C} belongs to me, now.  I shall feed\nyour living flesh to my minions.\"",
  "quest.wiz.nemesis_wantsit.synopsis": "[\"Thief!  {qo|C} belongs to me, now.  I shall feed your living flesh to my minions.\"]",
  "quest.wiz.nexttime": "Once again, you are back at {qH}.",
  "quest.wiz.offeredit": "{ql|C} notices {qo} in your possession,\nbeams at you and says:\n\n    \"I knew you could defeat {qn} and retrieve\n    {qo}.  We shall never forget this\n    brave service.\n\n    \"Take {qo_he} with you in your quest for the Amulet of Yendor.\n    I can sense that it has attuned {qo_him}self to you already.\n\n    \"May {qd} guide you in your quest, and keep you from harm.\"",
  "quest.wiz.offeredit.synopsis": "[Take {qo} with you in your quest for the Amulet.]",
  "quest.wiz.offeredit2": "\"You are the keeper of {qo} now.  It is time to\nrecover the /other/ Amulet.  The Dungeons of Doom await your return through\nthe magic portal which brought you here.\"",
  "quest.wiz.offeredit2.synopsis": "[Keep {qo}, return through the portal to The Dungeons of Doom; find the other Amulet.]",
  "quest.wiz.othertime": "You are back at {qH}.\nYou have an odd feeling this may be the last time you ever come here.",
  "quest.wiz.othertime.synopsis": "[You are back at {qH}. You have an odd feeling this may be the last time you ever come here.]",
  "quest.wiz.posthanks": "\"Come near, my {qS}, and share your adventures with me.\nSo, have you succeeded in your quest for the Amulet of Yendor?\"",
  "quest.wiz.posthanks.synopsis": "[\"Come near, my {qS}, and share your adventures with me. So, have you succeeded in your quest for the Amulet of Yendor?\"]",
};
